import { useDocumentOperation } from 'sanity'
import { useRouter } from 'sanity/router'
import { useClient } from 'sanity'
import { CopyIcon } from '@sanity/icons'
import { useCallback, useState } from 'react'

export function DuplicateAction(props: any) {
    const { patch: _patch, publish: _publish } = useDocumentOperation(props.id, props.type)
    const router = useRouter()
    const client = useClient({ apiVersion: '2024-01-01' })
    const [isDuplicating, setIsDuplicating] = useState(false)

    const onHandle = useCallback(async () => {
        setIsDuplicating(true)

        try {
            // 1. Fetch the current document
            const doc = await client.fetch(`*[_id == $id][0]`, { id: props.id })

            if (!doc) {
                setIsDuplicating(false)
                return
            }

            // 2. Prepare the new document (remove system fields)
            const { _id: _unusedId, _createdAt: _unusedCreated, _updatedAt: _unusedUpdated, _rev: _unusedRev, slug: _unusedSlug, ...rest } = doc

            const newDoc = {
                ...rest,
                _type: 'college',
                name: `${doc.name} (Copy)`,
                isVisible: false, // Default to hidden
                // Explicitly clear slug to avoid conflicts
                slug: undefined,
                // Reset sync status
                lastSyncedAt: undefined,
                detailsIdentifier: undefined
            }

            // 3. Create the new document
            const createdDoc = await client.create(newDoc)

            // 4. Navigate to the new document
            router.navigateIntent('edit', { id: createdDoc._id, type: createdDoc._type })

        } catch (err) {
            console.error('Error duplicating document:', err)
            alert('Failed to duplicate college')
        } finally {
            setIsDuplicating(false)
        }
    }, [props.id, client, router])

    if (props.type !== 'college') {
        return null
    }

    return {
        label: isDuplicating ? 'Duplicating...' : 'Duplicate College',
        icon: CopyIcon,
        onHandle,
        disabled: isDuplicating
    }
}

// Activity Log Widget
// Tracks and displays recent content changes

'use client'

import { Stack, Text, Button, Box, Badge, Flex, Select, Card } from '@sanity/ui'
import { useState, useEffect, useCallback } from 'react'
import { useClient } from 'sanity'
import { useRouter } from 'sanity/router'
import { Clock, FileText, Plus, Pencil, Eye, RefreshCw } from 'lucide-react'
import { apiVersion } from '../env'
import { WidgetCard, EmptyState } from './shared'

interface ActivityItem {
    _id: string
    _type: string
    _createdAt: string
    _updatedAt: string
    name: string
    isVisible?: boolean
    _rev?: string
    activityType?: 'created' | 'updated'
}

type ActivityType = 'all' | 'created' | 'updated'
type TimeRange = '1h' | '24h' | '7d' | '30d'

export function ActivityLogWidget() {
    const client = useClient({ apiVersion })
    const router = useRouter()
    const [activities, setActivities] = useState<ActivityItem[]>([])
    const [loading, setLoading] = useState(true)
    const [activityType, setActivityType] = useState<ActivityType>('all')
    const [timeRange, setTimeRange] = useState<TimeRange>('24h')
    const [autoRefresh, setAutoRefresh] = useState(false)

    const getTimeThreshold = useCallback((): string => {
        const now = new Date()
        switch (timeRange) {
            case '1h': return new Date(now.getTime() - 60 * 60 * 1000).toISOString()
            case '24h': return new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString()
            case '7d': return new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString()
            case '30d': return new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000).toISOString()
            default: return new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString()
        }
    }, [timeRange])

    const isNewlyCreated = useCallback((item: ActivityItem): boolean => {
        const created = new Date(item._createdAt).getTime()
        const updated = new Date(item._updatedAt).getTime()
        return (updated - created) < 60000
    }, [])

    const fetchActivities = useCallback(async () => {
        setLoading(true)
        try {
            const threshold = getTimeThreshold()
            let query = ''

            if (activityType === 'created') {
                query = `*[_type == "college" && _createdAt > $threshold] | order(_createdAt desc) [0...20]`
            } else if (activityType === 'updated') {
                query = `*[_type == "college" && _updatedAt > $threshold && dateTime(_updatedAt) > dateTime(_createdAt) + 60] | order(_updatedAt desc) [0...20]`
            } else {
                query = `*[_type == "college" && (_updatedAt > $threshold || _createdAt > $threshold)] | order(_updatedAt desc) [0...20]`
            }

            const items = await client.fetch(
                `${query} { _id, _type, _createdAt, _updatedAt, name, isVisible, _rev }`,
                { threshold }
            )

            const processedItems = items.map((item: ActivityItem) => ({
                ...item,
                activityType: isNewlyCreated(item) ? 'created' : 'updated'
            }))

            setActivities(processedItems)
        } catch (error) {
            console.error('Failed to fetch activities:', error)
        } finally {
            setLoading(false)
        }
    }, [client, activityType, getTimeThreshold, isNewlyCreated])

    useEffect(() => {
        fetchActivities()
    }, [fetchActivities])

    useEffect(() => {
        let interval: NodeJS.Timeout | null = null
        if (autoRefresh) {
            interval = setInterval(fetchActivities, 30000)
        }
        return () => {
            if (interval) clearInterval(interval)
        }
    }, [autoRefresh, fetchActivities])



    const formatTime = (dateString: string): string => {
        const date = new Date(dateString)
        const now = new Date()
        const diff = now.getTime() - date.getTime()
        const seconds = Math.floor(diff / 1000)
        const minutes = Math.floor(diff / 60000)
        const hours = Math.floor(diff / 3600000)
        const days = Math.floor(diff / 86400000)

        if (seconds < 60) return 'Just now'
        if (minutes < 60) return `${minutes}m ago`
        if (hours < 24) return `${hours}h ago`
        if (days < 7) return `${days}d ago`
        return date.toLocaleDateString()
    }

    const navigateToDocument = (id: string) => {
        router.navigateIntent('edit', { id: id?.replace('drafts.', ''), type: 'college' })
    }

    const getActivityIcon = (item: ActivityItem) => {
        if (item.activityType === 'created') {
            return <Plus size={14} style={{ color: '#37b24d' }} />
        }
        return <Pencil size={14} style={{ color: '#228be6' }} />
    }

    const stats = {
        total: activities.length,
        created: activities.filter((a) => a.activityType === 'created').length,
        updated: activities.filter((a) => a.activityType === 'updated').length
    }

    return (
        <WidgetCard
            title="Activity Log"
            icon={<Clock size={18} />}
            iconColor="#228be6"
            headerGradient="linear-gradient(135deg, #3b82f6 0%, #2563eb 100%)"
            loading={loading}
            collapsible
            actions={
                <Flex gap={1}>
                    <Button
                        icon={RefreshCw}
                        onClick={fetchActivities}
                        disabled={loading}
                        mode="bleed"
                        style={{ color: 'white' }}
                        title="Refresh"
                    />
                    <Button
                        text={autoRefresh ? 'Auto' : 'Off'}
                        onClick={() => setAutoRefresh(!autoRefresh)}
                        mode="bleed"
                        style={{
                            color: 'white',
                            background: autoRefresh ? 'rgba(255,255,255,0.2)' : 'transparent'
                        }}
                        fontSize={0}
                        title={autoRefresh ? 'Auto-refresh ON' : 'Auto-refresh OFF'}
                    />
                </Flex>
            }
            footer={autoRefresh ? (
                <Text size={0} muted style={{ textAlign: 'center' }}>
                    ⚡ Auto-refreshing every 30 seconds
                </Text>
            ) : undefined}
        >
            <Stack space={4}>
                {/* Filters */}
                <Flex gap={2}>
                    <Box flex={1}>
                        <Select
                            value={activityType}
                            onChange={(e) => setActivityType(e.currentTarget.value as ActivityType)}
                            fontSize={1}
                        >
                            <option value="all">All Activity</option>
                            <option value="created">Created Only</option>
                            <option value="updated">Updated Only</option>
                        </Select>
                    </Box>
                    <Box flex={1}>
                        <Select
                            value={timeRange}
                            onChange={(e) => setTimeRange(e.currentTarget.value as TimeRange)}
                            fontSize={1}
                        >
                            <option value="1h">Last Hour</option>
                            <option value="24h">Last 24 Hours</option>
                            <option value="7d">Last 7 Days</option>
                            <option value="30d">Last 30 Days</option>
                        </Select>
                    </Box>
                </Flex>

                {/* Stats */}
                <Flex gap={2}>
                    <Badge tone="default">{stats.total} Total</Badge>
                    <Badge tone="positive">{stats.created} Created</Badge>
                    <Badge tone="primary">{stats.updated} Updated</Badge>
                </Flex>

                {/* Activity List */}
                <Box
                    padding={3}
                    style={{
                        background: 'rgba(255,255,255,0.03)',
                        borderRadius: 8,
                        maxHeight: '350px',
                        overflowY: 'auto'
                    }}
                >
                    {activities.length > 0 ? (
                        <Stack space={2}>
                            {activities.map((item: any) => (
                                <Card
                                    key={`${item._id}-${item._updatedAt}`}
                                    padding={2}
                                    tone="transparent"
                                    style={{ cursor: 'pointer', transition: 'background 0.15s' }}
                                    onClick={() => navigateToDocument(item._id)}
                                >
                                    <Flex justify="space-between" align="center">
                                        <Flex align="center" gap={2} flex={1}>
                                            {getActivityIcon(item)}
                                            <Stack space={1} flex={1}>
                                                <Text size={1} weight="medium">{item.name}</Text>
                                                <Flex gap={2} align="center">
                                                    <Badge
                                                        tone={item.activityType === 'created' ? 'positive' : 'primary'}
                                                        fontSize={0}
                                                    >
                                                        {item.activityType === 'created' ? 'Created' : 'Updated'}
                                                    </Badge>
                                                    {item.isVisible && (
                                                        <Badge tone="positive" fontSize={0}>
                                                            <Eye size={10} style={{ marginRight: 2 }} />
                                                            Visible
                                                        </Badge>
                                                    )}
                                                </Flex>
                                            </Stack>
                                        </Flex>
                                        <Text size={0} muted>
                                            {formatTime(item._updatedAt)}
                                        </Text>
                                    </Flex>
                                </Card>
                            ))}
                        </Stack>
                    ) : (
                        <EmptyState
                            icon={<FileText size={32} />}
                            title="No activity in this time range"
                            description="Try expanding the time range"
                        />
                    )}
                </Box>
            </Stack>
        </WidgetCard>
    )
}

// Analytics Dashboard Widget
// Displays key metrics and insights about college data

'use client'

import { Stack, Text, Grid, Badge, Flex, Box, Button } from '@sanity/ui'
import { useState, useEffect, useCallback } from 'react'
import { useClient } from 'sanity'
import { TrendingUp, Eye, EyeOff, Calendar, Award, Building2, MapPin, RefreshCw } from 'lucide-react'
import { apiVersion } from '../env'
import { WidgetCard, StatsGrid, ProgressBar } from './shared'

interface AnalyticsData {
    total: number
    visible: number
    hidden: number
    withDetails: number
    withoutDetails: number
    byType: { type: string; count: number }[]
    byLocation: { location: string; count: number }[]
    recentlyAdded: number // Last 30 days
    recentlyUpdated: number // Last 7 days
    completionRate: number // Percentage with all required fields
    avgQualityScore: number
}


interface AnalyticsCollege {
    _id: string
    _createdAt: string
    _updatedAt: string
    name: string
    type?: string
    location?: string
    isVisible?: boolean
    logo?: unknown
    description?: string
    detailsReference?: unknown
    highlights?: string[]
}

export function AnalyticsDashboardWidget() {
    const client = useClient({ apiVersion })
    const [loading, setLoading] = useState(true)
    const [data, setData] = useState<AnalyticsData | null>(null)

    // eslint-disable-next-line react-hooks/exhaustive-deps
    const fetchAnalytics = useCallback(async () => {
        setLoading(true)
        try {
            // Fetch all colleges with necessary fields
            const colleges = await client.fetch<AnalyticsCollege[]>(`
                *[_type == "college"] {
                    _id,
                    _createdAt,
                    _updatedAt,
                    name,
                    type,
                    location,
                    isVisible,
                    logo,
                    description,
                    detailsReference,
                    highlights
                }
            `)

            const now = new Date()
            const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000)
            const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000)

            // Calculate metrics
            const total = colleges.length
            const visible = colleges.filter(c => c.isVisible).length
            const hidden = total - visible
            const withDetails = colleges.filter(c => c.detailsReference).length
            const withoutDetails = total - withDetails

            // Recent activity
            const recentlyAdded = colleges.filter(c =>
                new Date(c._createdAt) > thirtyDaysAgo
            ).length
            const recentlyUpdated = colleges.filter(c =>
                new Date(c._updatedAt) > sevenDaysAgo
            ).length

            // By Type
            const typeMap = new Map<string, number>()
            colleges.forEach(c => {
                const type = c.type || 'Unknown'
                typeMap.set(type, (typeMap.get(type) || 0) + 1)
            })
            const byType = Array.from(typeMap.entries())
                .map(([type, count]) => ({ type, count }))
                .sort((a, b) => b.count - a.count)

            // By Location
            const locationMap = new Map<string, number>()
            colleges.forEach(c => {
                const location = c.location || 'Unknown'
                locationMap.set(location, (locationMap.get(location) || 0) + 1)
            })
            const byLocation = Array.from(locationMap.entries())
                .map(([location, count]) => ({ location, count }))
                .sort((a, b) => b.count - a.count)
                .slice(0, 5) // Top 5 locations

            // Completion rate (colleges with logo, description, and highlights)
            const complete = colleges.filter(c =>
                c.logo && c.description && c.highlights && c.highlights.length > 0
            ).length
            const completionRate = total > 0 ? Math.round((complete / total) * 100) : 0

            // Average quality score
            const qualityScores = colleges.map(c => {
                let score = 0
                if (c.logo) score += 25
                if (c.description) score += 25
                if (c.detailsReference) score += 25
                if (c.highlights && c.highlights.length > 0) score += 25
                return score
            })
            const avgQualityScore = qualityScores.length > 0
                ? Math.round(qualityScores.reduce((a, b) => a + b, 0) / qualityScores.length)
                : 0

            setData({
                total,
                visible,
                hidden,
                withDetails,
                withoutDetails,
                byType,
                byLocation,
                recentlyAdded,
                recentlyUpdated,
                completionRate,
                avgQualityScore
            })
        } catch (error) {
            console.error('Failed to fetch analytics:', error)
        } finally {
            setLoading(false)
        }
    }, [client])

    useEffect(() => {
        fetchAnalytics()
    }, [fetchAnalytics])

    return (
        <WidgetCard
            title="Analytics Dashboard"
            icon={<TrendingUp size={18} />}
            iconColor="#6366f1"
            loading={loading}
            collapsible
            headerGradient="linear-gradient(135deg, #6366f1 0%, #8b5cf6 100%)"
            actions={
                <Button
                    icon={RefreshCw}
                    mode="bleed"
                    onClick={fetchAnalytics}
                    style={{ color: 'white' }}
                />
            }
        >
            {data && (
                <Stack space={4}>
                    {/* Key Metrics */}
                    <StatsGrid
                        columns={4}
                        stats={[
                            { label: 'Total', value: data.total, tone: 'primary', icon: <Building2 size={16} /> },
                            { label: 'Visible', value: data.visible, tone: 'positive', icon: <Eye size={16} /> },
                            { label: 'Hidden', value: data.hidden, tone: 'caution', icon: <EyeOff size={16} /> },
                            { label: 'Quality', value: `${data.avgQualityScore}%`, icon: <Award size={16} /> }
                        ]}
                    />

                    {/* Activity Metrics */}
                    <Box padding={3} style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 8 }}>
                        <Stack space={2}>
                            <Text size={1} weight="semibold">Recent Activity</Text>
                            <Grid columns={2} gap={2}>
                                <Flex align="center" gap={2}>
                                    <Calendar size={14} style={{ opacity: 0.5 }} />
                                    <Text size={1}>
                                        <Badge tone="positive">{data.recentlyAdded}</Badge> added (30d)
                                    </Text>
                                </Flex>
                                <Flex align="center" gap={2}>
                                    <Calendar size={14} style={{ opacity: 0.5 }} />
                                    <Text size={1}>
                                        <Badge tone="primary">{data.recentlyUpdated}</Badge> updated (7d)
                                    </Text>
                                </Flex>
                            </Grid>
                        </Stack>
                    </Box>

                    {/* Completion Rate */}
                    <Box padding={3} style={{
                        background: data.completionRate >= 80 ? 'rgba(16, 185, 129, 0.1)' : data.completionRate >= 50 ? 'rgba(245, 158, 11, 0.1)' : 'rgba(239, 68, 68, 0.1)',
                        borderRadius: 8
                    }}>
                        <Stack space={2}>
                            <Flex justify="space-between" align="center">
                                <Text size={1} weight="semibold">Data Completion</Text>
                                <Text size={2} weight="bold">{data.completionRate}%</Text>
                            </Flex>
                            <ProgressBar
                                value={data.completionRate}
                                color={data.completionRate >= 80 ? '#10b981' : data.completionRate >= 50 ? '#f59e0b' : '#ef4444'}
                            />
                        </Stack>
                    </Box>

                    {/* Distribution */}
                    <Grid columns={2} gap={3}>
                        {/* By Type */}
                        <Box padding={3} style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 8 }}>
                            <Stack space={2}>
                                <Text size={0} weight="semibold" muted>BY TYPE</Text>
                                {data.byType.map(({ type, count }) => (
                                    <Flex key={type} justify="space-between" align="center">
                                        <Text size={1}>{type}</Text>
                                        <Badge tone="primary">{count}</Badge>
                                    </Flex>
                                ))}
                            </Stack>
                        </Box>

                        {/* Top Locations */}
                        <Box padding={3} style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 8 }}>
                            <Stack space={2}>
                                <Flex align="center" gap={1}>
                                    <MapPin size={12} />
                                    <Text size={0} weight="semibold" muted>TOP LOCATIONS</Text>
                                </Flex>
                                {data.byLocation.map(({ location, count }) => (
                                    <Flex key={location} justify="space-between" align="center">
                                        <Text size={1}>{location}</Text>
                                        <Badge tone="default">{count}</Badge>
                                    </Flex>
                                ))}
                            </Stack>
                        </Box>
                    </Grid>
                </Stack>
            )}
        </WidgetCard>
    )
}

// Backup & Restore Widget
// Create and restore data backups

'use client'

import { Stack, Text, Button, Box, Badge, Flex, Select } from '@sanity/ui'
import { useState, useEffect, useCallback } from 'react'
import { useClient } from 'sanity'
import { Database, Download, Upload, Clock, Trash2, Shield, HardDrive } from 'lucide-react'
import { apiVersion } from '../env'
import { WidgetCard, StatsGrid } from './shared'

interface BackupMetadata {
    id: string
    name: string
    timestamp: string
    documentCount: number
    size: string
    type: 'full' | 'colleges' | 'custom'
}

interface BackupData {
    metadata: BackupMetadata
    documents: Record<string, unknown>[]
}

export function BackupRestoreWidget() {
    const client = useClient({ apiVersion })
    const [backups, setBackups] = useState<BackupMetadata[]>([])
    const [creating, setCreating] = useState(false)
    const [restoring, setRestoring] = useState(false)
    const [backupType, setBackupType] = useState<'full' | 'colleges'>('colleges')
    const [lastBackup, setLastBackup] = useState<string | null>(null)
    const [stats, setStats] = useState({ colleges: 0, posts: 0, settings: 0 })
    const [loading, setLoading] = useState(true)

    useEffect(() => {
        loadBackups()
        fetchStats()
    }, [loadBackups, fetchStats])

    const loadBackups = useCallback(() => {
        try {
            const stored = localStorage.getItem('sanity-backups-metadata')
            if (stored) setBackups(JSON.parse(stored))
            const last = localStorage.getItem('sanity-last-backup')
            if (last) setLastBackup(last)
        } catch (error) {
            console.error('Failed to load backups:', error)
        }
    }, [])

    const fetchStats = useCallback(async () => {
        setLoading(true)
        try {
            const [colleges, posts, settings] = await Promise.all([
                client.fetch<number>('count(*[_type == "college"])'),
                client.fetch<number>('count(*[_type == "post"])'),
                client.fetch<number>('count(*[_type == "siteSettings"])')
            ])
            setStats({ colleges, posts, settings })
        } catch (error) {
            console.error('Failed to fetch stats:', error)
        } finally {
            setLoading(false)
        }
    }, [client])

    const createBackup = async () => {
        setCreating(true)
        try {
            let query = backupType === 'full'
                ? '*[_type in ["college", "collegeCutoff", "collegeDetail", "post", "author", "category", "siteSettings", "timeline"]]'
                : '*[_type == "college"]'

            const documents = await client.fetch(query)

            const metadata: BackupMetadata = {
                id: `backup-${Date.now()}`,
                name: `${backupType === 'full' ? 'Full' : 'Colleges'} Backup`,
                timestamp: new Date().toISOString(),
                documentCount: documents.length,
                size: formatBytes(new Blob([JSON.stringify(documents)]).size),
                type: backupType
            }

            const backup: BackupData = { metadata, documents }
            const dataStr = JSON.stringify(backup, null, 2)
            const dataBlob = new Blob([dataStr], { type: 'application/json' })
            const url = URL.createObjectURL(dataBlob)
            const link = document.createElement('a')
            link.href = url
            link.download = `sanity-backup-${backupType}-${new Date().toISOString().split('T')[0]}.json`
            link.click()
            URL.revokeObjectURL(url)

            const updatedBackups = [metadata, ...backups].slice(0, 10)
            setBackups(updatedBackups)
            localStorage.setItem('sanity-backups-metadata', JSON.stringify(updatedBackups))
            localStorage.setItem('sanity-last-backup', metadata.timestamp)
            setLastBackup(metadata.timestamp)

            alert(`✓ Backup created!\n${documents.length} documents backed up.`)
        } catch (error) {
            console.error('Backup failed:', error)
            alert('Backup failed. See console for details.')
        } finally {
            setCreating(false)
        }
    }

    const handleRestore = async (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0]
        if (!file) return

        setRestoring(true)
        try {
            const text = await file.text()
            const backup: BackupData = JSON.parse(text)

            if (!backup.metadata || !backup.documents) {
                throw new Error('Invalid backup file format')
            }

            const confirmed = window.confirm(
                `⚠️ RESTORE BACKUP\n\n` +
                `Restore ${backup.documents.length} documents from:\n` +
                `${backup.metadata.name}\n` +
                `Created: ${new Date(backup.metadata.timestamp).toLocaleString()}\n\n` +
                `Existing documents will be OVERWRITTEN.\n\nContinue?`
            )

            if (!confirmed) {
                setRestoring(false)
                return
            }

            const batchSize = 50
            let restored = 0, failed = 0

            for (let i = 0; i < backup.documents.length; i += batchSize) {
                const batch = backup.documents.slice(i, i + batchSize)
                const transaction = client.transaction()
                batch.forEach((doc: Record<string, unknown>) => {
                    // eslint-disable-next-line @typescript-eslint/no-unused-vars
                    const { _rev, ...docWithoutRev } = doc
                    transaction.createOrReplace(docWithoutRev)
                })
                try {
                    await transaction.commit()
                    restored += batch.length
                } catch (_err) {
                    failed += batch.length
                }
            }

            alert(`✓ Restored: ${restored} documents\n✗ Failed: ${failed} documents`)
            fetchStats()
        } catch (error) {
            alert('Restore failed. Make sure it\'s a valid backup file.')
        } finally {
            setRestoring(false)
            event.target.value = ''
        }
    }

    const deleteBackupMetadata = (id: string) => {
        const updated = backups.filter(b => b.id !== id)
        setBackups(updated)
        localStorage.setItem('sanity-backups-metadata', JSON.stringify(updated))
    }

    const formatBytes = (bytes: number): string => {
        if (bytes === 0) return '0 B'
        const k = 1024, sizes = ['B', 'KB', 'MB', 'GB']
        const i = Math.floor(Math.log(bytes) / Math.log(k))
        return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i]
    }

    const formatDate = (dateStr: string): string => {
        const date = new Date(dateStr)
        return date.toLocaleDateString() + ' ' + date.toLocaleTimeString()
    }

    const getTimeSinceBackup = (): string => {
        if (!lastBackup) return 'Never'
        const diff = Date.now() - new Date(lastBackup).getTime()
        const hours = Math.floor(diff / 3600000)
        const days = Math.floor(diff / 86400000)
        if (hours < 1) return 'Just now'
        if (hours < 24) return `${hours}h ago`
        if (days < 7) return `${days}d ago`
        return new Date(lastBackup).toLocaleDateString()
    }

    const shouldBackup = (): boolean => {
        if (!lastBackup) return true
        return (Date.now() - new Date(lastBackup).getTime()) / 86400000 > 7
    }

    return (
        <WidgetCard
            title="Backup & Restore"
            icon={<Shield size={18} />}
            iconColor="#10b981"
            headerGradient="linear-gradient(135deg, #10b981 0%, #059669 100%)"
            loading={loading}
            collapsible
            actions={shouldBackup() && (
                <Badge tone="caution" style={{ background: 'rgba(255,255,255,0.2)', color: 'white' }}>
                    Backup Needed
                </Badge>
            )}
            footer={
                <Text size={0} muted style={{ textAlign: 'center' }}>
                    💡 Tip: Create backups before major changes
                </Text>
            }
        >
            <Stack space={4}>
                {/* Stats */}
                <StatsGrid
                    columns={3}
                    stats={[
                        { label: 'Colleges', value: stats.colleges, tone: 'primary' },
                        { label: 'Posts', value: stats.posts },
                        { label: 'Last Backup', value: getTimeSinceBackup() }
                    ]}
                />

                {/* Backup Controls */}
                <Box padding={3} style={{ background: 'rgba(16, 185, 129, 0.1)', borderRadius: 8 }}>
                    <Stack space={3}>
                        <Flex align="center" gap={2}>
                            <Download size={16} />
                            <Text size={1} weight="semibold">Create Backup</Text>
                        </Flex>
                        <Flex gap={2}>
                            <Box flex={1}>
                                <Select
                                    value={backupType}
                                    onChange={(e) => setBackupType(e.currentTarget.value as 'full' | 'colleges')}
                                    fontSize={1}
                                >
                                    <option value="colleges">Colleges Only ({stats.colleges})</option>
                                    <option value="full">Full Backup (All)</option>
                                </Select>
                            </Box>
                            <Button
                                text={creating ? 'Creating...' : 'Backup'}
                                icon={Database}
                                onClick={createBackup}
                                disabled={creating}
                                tone="positive"
                                fontSize={1}
                            />
                        </Flex>
                    </Stack>
                </Box>

                {/* Restore Controls */}
                <Box padding={3} style={{ background: 'rgba(245, 158, 11, 0.1)', borderRadius: 8 }}>
                    <Stack space={3}>
                        <Flex align="center" gap={2}>
                            <Upload size={16} />
                            <Text size={1} weight="semibold">Restore from Backup</Text>
                        </Flex>
                        <Box>
                            <input
                                type="file"
                                accept=".json"
                                onChange={handleRestore}
                                disabled={restoring}
                                style={{ display: 'none' }}
                                id="restore-input"
                            />
                            <label htmlFor="restore-input">
                                <Button
                                    as="span"
                                    text={restoring ? 'Restoring...' : 'Select File'}
                                    icon={Upload}
                                    disabled={restoring}
                                    mode="ghost"
                                    fontSize={1}
                                    style={{ cursor: restoring ? 'not-allowed' : 'pointer' }}
                                />
                            </label>
                        </Box>
                        <Text size={0} muted>⚠️ Will overwrite existing documents</Text>
                    </Stack>
                </Box>

                {/* Backup History */}
                {backups.length > 0 && (
                    <Box padding={3} style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 8 }}>
                        <Stack space={2}>
                            <Flex align="center" gap={2}>
                                <Clock size={14} />
                                <Text size={1} weight="semibold">History</Text>
                                <Badge tone="default">{backups.length}</Badge>
                            </Flex>
                            <Stack space={1} style={{ maxHeight: '150px', overflowY: 'auto' }}>
                                {backups.map(backup => (
                                    <Flex key={backup.id} justify="space-between" align="center">
                                        <Stack space={0}>
                                            <Flex align="center" gap={2}>
                                                <HardDrive size={12} style={{ opacity: 0.5 }} />
                                                <Text size={1}>{backup.name}</Text>
                                                <Badge tone="primary" fontSize={0}>{backup.size}</Badge>
                                            </Flex>
                                            <Text size={0} muted>{formatDate(backup.timestamp)}</Text>
                                        </Stack>
                                        <Button
                                            icon={Trash2}
                                            mode="bleed"
                                            tone="critical"
                                            onClick={() => deleteBackupMetadata(backup.id)}
                                            fontSize={0}
                                        />
                                    </Flex>
                                ))}
                            </Stack>
                        </Stack>
                    </Box>
                )}
            </Stack>
        </WidgetCard>
    )
}

// Batch Operations Widget
// Perform bulk operations on selected colleges

'use client'

import { Stack, Text, Button, Box, Badge, Flex, Select, Checkbox, TextInput, Card } from '@sanity/ui'
import { useState, useEffect, useCallback } from 'react'
import { useClient } from 'sanity'
import { Layers, CheckSquare, Square, Trash2, Eye, EyeOff, RefreshCw, AlertTriangle, Check } from 'lucide-react'
import { apiVersion } from '../env'
import { WidgetCard, EmptyState } from './shared'

interface College {
    _id: string
    name: string
    location: string
    type: string
    isVisible: boolean
}

type Operation = 'show' | 'hide' | 'setType' | 'setLocation' | 'delete'

export function BatchOperationsWidget() {
    const client = useClient({ apiVersion })
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    const [colleges, setColleges] = useState<College[]>([])
    const [selected, setSelected] = useState<Set<string>>(new Set())
    const [loading, setLoading] = useState(true)
    const [operating, setOperating] = useState(false)
    const [operation, setOperation] = useState<Operation>('show')
    const [operationValue, setOperationValue] = useState('')
    const [searchTerm, setSearchTerm] = useState('')
    const [filterType, setFilterType] = useState<'all' | 'visible' | 'hidden'>('all')

    useEffect(() => { fetchColleges() }, [fetchColleges])

    const fetchColleges = useCallback(async () => {
        setLoading(true)
        try {
            const data = await client.fetch<College[]>(`*[_type == "college"] | order(name asc) { _id, name, location, type, isVisible }`)
            setColleges(data)
        } catch (error) {
            console.error('Failed to fetch colleges:', error)
        } finally {
            setLoading(false)
        }
    }, [client])

    const filteredColleges = colleges.filter(college => {
        const matchesSearch = !searchTerm || college.name.toLowerCase().includes(searchTerm.toLowerCase())
        const matchesFilter = filterType === 'all' ||
            (filterType === 'visible' && college.isVisible) ||
            (filterType === 'hidden' && !college.isVisible)
        return matchesSearch && matchesFilter
    })

    const toggleSelect = (id: string) => {
        const newSelected = new Set(selected)
        if (newSelected.has(id)) newSelected.delete(id)
        else newSelected.add(id)
        setSelected(newSelected)
    }

    const selectAll = () => {
        if (selected.size === filteredColleges.length) setSelected(new Set())
        else setSelected(new Set(filteredColleges.map(c => c._id)))
    }

    const executeOperation = async () => {
        if (selected.size === 0) return alert('Select at least one college')

        const operationLabels: Record<Operation, string> = {
            show: 'make visible', hide: 'hide', setType: `set type to "${operationValue}"`,
            setLocation: `update location to "${operationValue}"`, delete: 'permanently DELETE'
        }

        if (!window.confirm(`${operation === 'delete' ? '⚠️ ' : ''}${operationLabels[operation]} ${selected.size} college(s)?`)) return

        setOperating(true)
        let success = 0

        try {
            const selectedIds = Array.from(selected)
            if (operation === 'delete') {
                const transaction = client.transaction()
                selectedIds.forEach(id => transaction.delete(id))
                await transaction.commit()
                success = selectedIds.length
            } else {
                for (const id of selectedIds) {
                    try {
                        let patch = client.patch(id)
                        if (operation === 'show') patch = patch.set({ isVisible: true })
                        else if (operation === 'hide') patch = patch.set({ isVisible: false })
                        else if (operation === 'setType' && operationValue) patch = patch.set({ type: operationValue })
                        else if (operation === 'setLocation' && operationValue) patch = patch.set({ location: operationValue })
                        await patch.commit()
                        success++
                    } catch (err) {
                        console.error(`Failed to update ${id}:`, err)
                    }
                }
            }

            alert(`✓ Updated ${success} colleges`)
            await fetchColleges()
            setSelected(new Set())
            setOperationValue('')
        } catch (error) {
            console.error('Operation failed:', error)
            alert('Operation failed')
        } finally {
            setOperating(false)
        }
    }

    const getOperationRequiresValue = () => operation === 'setType' || operation === 'setLocation'

    return (
        <WidgetCard
            title="Batch Operations"
            icon={<Layers size={18} />}
            iconColor="#7c3aed"
            headerGradient="linear-gradient(135deg, #7c3aed 0%, #6d28d9 100%)"
            loading={loading}
            collapsible
            actions={
                <Button icon={RefreshCw} onClick={fetchColleges} disabled={loading} mode="bleed" style={{ color: 'white' }} />
            }
        >
            <Stack space={4}>
                {/* Stats */}
                <Flex gap={2} wrap="wrap">
                    <Badge tone={selected.size > 0 ? 'primary' : 'default'}>{selected.size} selected</Badge>
                    <Badge tone="default">{colleges.length} total</Badge>
                    <Badge tone="positive">{colleges.filter(c => c.isVisible).length} visible</Badge>
                    <Badge tone="caution">{colleges.filter(c => !c.isVisible).length} hidden</Badge>
                </Flex>

                {/* Search & Filter */}
                <Flex gap={2}>
                    <Box flex={1}>
                        <TextInput placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.currentTarget.value)} fontSize={1} />
                    </Box>
                    <Select value={filterType} onChange={(e) => setFilterType(e.currentTarget.value as 'all' | 'visible' | 'hidden')} fontSize={1}>
                        <option value="all">All</option>
                        <option value="visible">Visible</option>
                        <option value="hidden">Hidden</option>
                    </Select>
                </Flex>

                {/* Quick Select */}
                <Flex gap={2}>
                    <Button text={selected.size === filteredColleges.length ? 'Deselect' : 'Select All'} icon={selected.size === filteredColleges.length ? Square : CheckSquare} onClick={selectAll} mode="ghost" fontSize={0} />
                    <Button text="Visible" icon={Eye} onClick={() => setSelected(new Set(colleges.filter(c => c.isVisible).map(c => c._id)))} mode="ghost" fontSize={0} />
                    <Button text="Hidden" icon={EyeOff} onClick={() => setSelected(new Set(colleges.filter(c => !c.isVisible).map(c => c._id)))} mode="ghost" fontSize={0} />
                </Flex>

                {/* College List */}
                <Box padding={2} style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 8, maxHeight: '200px', overflowY: 'auto' }}>
                    {filteredColleges.length > 0 ? (
                        <Stack space={2}>
                            {filteredColleges.map(college => (
                                <Card
                                    key={college._id}
                                    padding={2}
                                    radius={2}
                                    tone="transparent"
                                    border
                                    style={{
                                        background: selected.has(college._id) ? 'rgba(124, 58, 237, 0.15)' : 'transparent',
                                        cursor: 'pointer'
                                    }}
                                >
                                    <Flex
                                        align="center"
                                        gap={2}
                                        onClick={() => toggleSelect(college._id)}
                                    >
                                        <Box onClick={(e) => e.stopPropagation()}>
                                            <Checkbox
                                                checked={selected.has(college._id)}
                                                onChange={() => toggleSelect(college._id)}
                                            />
                                        </Box>
                                        <Stack space={0} flex={1} style={{ minWidth: 0 }}>
                                            <Text size={1} style={{ wordBreak: 'break-word', lineHeight: 1.2 }}>{college.name}</Text>
                                            <Text size={0} muted style={{ wordBreak: 'break-word', marginTop: '6px' }}>{college.location || 'No location'} • {college.type || 'No type'}</Text>
                                        </Stack>
                                        <Badge tone={college.isVisible ? 'positive' : 'caution'} fontSize={0}>
                                            {college.isVisible ? 'Visible' : 'Hidden'}
                                        </Badge>
                                    </Flex>
                                </Card>
                            ))}
                        </Stack>
                    ) : (
                        <EmptyState title="No results" description="Try a different search" />
                    )}
                </Box>

                {/* Operation Selection */}
                <Box padding={3} style={{ background: operation === 'delete' ? 'rgba(239, 68, 68, 0.1)' : 'rgba(124, 58, 237, 0.1)', borderRadius: 8 }}>
                    <Stack space={3}>
                        <Text size={0} weight="semibold" muted>SELECT OPERATION</Text>
                        <Select
                            value={operation}
                            onChange={(e) => { setOperation(e.currentTarget.value as Operation); setOperationValue('') }}
                            fontSize={1}
                        >
                            <option value="show">Make Visible</option>
                            <option value="hide">Hide</option>
                            <option value="setType">Set Type</option>
                            <option value="setLocation">Update Location</option>
                            <option value="delete">⚠️ Delete (Permanent)</option>
                        </Select>

                        {getOperationRequiresValue() && (
                            <TextInput
                                placeholder={operation === 'setType' ? 'e.g., Government, Private' : 'e.g., Kolkata'}
                                value={operationValue}
                                onChange={(e) => setOperationValue(e.currentTarget.value)}
                                fontSize={1}
                            />
                        )}

                        <Button
                            text={operating ? 'Processing...' : `Apply to ${selected.size}`}
                            icon={operation === 'delete' ? Trash2 : Check}
                            onClick={executeOperation}
                            disabled={operating || selected.size === 0 || (getOperationRequiresValue() && !operationValue)}
                            tone={operation === 'delete' ? 'critical' : 'positive'}
                            fontSize={1}
                        />

                        {operation === 'delete' && (
                            <Flex align="center" gap={2}>
                                <AlertTriangle size={14} style={{ color: '#ef4444' }} />
                                <Text size={0} style={{ color: '#ef4444' }}>Cannot be undone!</Text>
                            </Flex>
                        )}
                    </Stack>
                </Box>
            </Stack>
        </WidgetCard>
    )
}

'use client'

import { Stack, Text, TextArea, Button, Box, Select, Badge, Flex, Card } from '@sanity/ui'
import { useState, useEffect } from 'react'
import { useClient } from 'sanity'
import { Sparkles, Eye, Play, CheckCircle2, XCircle } from 'lucide-react'
import {
    AVAILABLE_VARIABLES,
    processTemplate,
    validateTemplate,
    getProcessedLength
} from '../utils/templateEngine'
import {
    bulkUpdateSeoDescriptions,
    fetchCollegesForPreview,
    getCollegeCount,
    type BulkUpdateProgress,
    type BulkUpdateResult
} from '../utils/bulkUpdate'
import { apiVersion } from '../env'
import { WidgetCard, ProgressBar } from './shared'

export function BulkSeoWidget() {
    const client = useClient({ apiVersion })

    const [template, setTemplate] = useState('')
    const [filter, setFilter] = useState<'all' | 'visible' | 'hidden'>('all')
    interface PreviewItem {
        _id: string
        name: string
        old: string
        new: string
        isVisible?: boolean
    }

    const [preview, setPreview] = useState<PreviewItem[]>([])
    const [totalCount, setTotalCount] = useState(0)
    const [updating, setUpdating] = useState(false)
    const [progress, setProgress] = useState<BulkUpdateProgress>({ current: 0, total: 0 })
    const [showResults, setShowResults] = useState(false)
    const [results, setResults] = useState<BulkUpdateResult[]>([])

    useEffect(() => { getCollegeCount(client, filter).then(setTotalCount) }, [filter, client])

    const validation = template ? validateTemplate(template) : { valid: false, errors: [], warnings: [] }
    const lengths = template ? getProcessedLength(template) : null

    const handlePreview = async () => {
        if (!validation.valid) return
        try {
            const colleges = await fetchCollegesForPreview(client, filter, 10)
            const previewed = colleges.map(c => ({
                _id: c._id, name: c.name, old: c.description || '(empty)',
                new: processTemplate(template, c), isVisible: c.isVisible
            }))
            setPreview(previewed)
            setShowResults(false)
        } catch (error) {
            alert('Preview failed')
        }
    }

    const handleApply = async () => {
        if (!validation.valid) return
        if (!window.confirm(`Apply SEO descriptions to ${totalCount} colleges?`)) return

        setUpdating(true)
        setProgress({ current: 0, total: totalCount })
        setShowResults(false)

        try {
            const baseQuery = '_type == "college"'
            const filterQuery = filter === 'all' ? baseQuery : `${baseQuery} && isVisible == ${filter === 'visible'}`
            const ids = await client.fetch(`*[${filterQuery}]._id`)
            const updateResults = await bulkUpdateSeoDescriptions(client, ids, template, (prog) => setProgress(prog))

            setResults(updateResults)
            setShowResults(true)
        } catch (error) {
            alert('Bulk update failed')
        } finally {
            setUpdating(false)
        }
    }

    const insertVariable = (variable: string) => setTemplate(prev => prev + variable)
    const successCount = results.filter(r => r.success).length
    const failCount = results.length - successCount

    return (
        <WidgetCard
            title="Bulk SEO Update"
            icon={<Sparkles size={18} />}
            iconColor="#ec4899"
            headerGradient="linear-gradient(135deg, #ec4899 0%, #db2777 100%)"
            collapsible
        >
            <Stack space={4}>
                {/* Available Variables */}
                <Box padding={3} style={{ background: 'rgba(236, 72, 153, 0.1)', borderRadius: 8 }}>
                    <Stack space={2}>
                        <Text size={0} weight="semibold" muted>AVAILABLE VARIABLES</Text>
                        <Flex gap={1} wrap="wrap">
                            {AVAILABLE_VARIABLES.map(v => (
                                <Badge key={v.key} tone="primary" style={{ cursor: 'pointer' }} onClick={() => insertVariable(v.key)}>
                                    {v.key}
                                </Badge>
                            ))}
                        </Flex>
                        <Text size={0} muted>Click to insert</Text>
                    </Stack>
                </Box>

                {/* Quick Templates */}
                <Select
                    value=""
                    onChange={(e) => { if (e.currentTarget.value) setTemplate(e.currentTarget.value) }}
                    fontSize={1}
                >
                    <option value="">Select template...</option>
                    <option value='"{college.name} - Best {college.type} College in {college.location} | WBJEE 2026"'>Standard</option>
                    <option value='"{college.name} ({college.shortName}) - Top Engineering College | Admissions 2026"'>With Acronym</option>
                    <option value='"{college.name} | {college.type} | {college.location} | WBJEE Cutoffs & Placements"'>SEO Focused</option>
                </Select>

                {/* Template Input */}
                <Stack space={2}>
                    <TextArea
                        rows={3}
                        value={template}
                        onChange={(e) => setTemplate(e.currentTarget.value)}
                        placeholder='"{college.name} - Best {college.type} College in {college.location}"'
                        fontSize={1}
                    />
                    {validation.errors.length > 0 && <Card padding={2} tone="critical"><Text size={0}>{validation.errors.join(', ')}</Text></Card>}
                    {validation.warnings.length > 0 && <Card padding={2} tone="caution"><Text size={0}>{validation.warnings.join(', ')}</Text></Card>}
                    {lengths && <Text size={0} muted>Length: {lengths.min}-{lengths.max} chars {lengths.avg >= 150 && lengths.avg <= 160 && '✓ Ideal'}</Text>}
                </Stack>

                {/* Filter & Count */}
                <Flex gap={2} align="center">
                    <Box flex={1}>
                        <Select value={filter} onChange={(e) => setFilter(e.currentTarget.value as 'all' | 'visible' | 'hidden')} fontSize={1}>
                            <option value="all">All ({totalCount})</option>
                            <option value="visible">Visible Only</option>
                            <option value="hidden">Hidden Only</option>
                        </Select>
                    </Box>
                    <Badge tone={filter === 'visible' ? 'positive' : filter === 'hidden' ? 'caution' : 'default'}>{totalCount}</Badge>
                </Flex>

                {/* Actions */}
                <Flex gap={2}>
                    <Button text="Preview" onClick={handlePreview} mode="ghost" tone="primary" icon={Eye} disabled={!validation.valid || updating} fontSize={1} />
                    <Button text={updating ? `${progress.current}/${progress.total}` : `Apply (${totalCount})`} onClick={handleApply} disabled={!validation.valid || updating || totalCount === 0} tone="positive" icon={updating ? undefined : Play} fontSize={1} style={{ flex: 1 }} />
                </Flex>

                {/* Progress */}
                {updating && <ProgressBar value={progress.current} max={progress.total} color="#ec4899" />}

                {/* Preview */}
                {preview.length > 0 && !showResults && (
                    <Box padding={3} style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 8, maxHeight: '200px', overflowY: 'auto' }}>
                        <Stack space={2}>
                            <Text size={0} weight="semibold" muted>PREVIEW</Text>
                            {preview.map((p) => (
                                <Card key={p._id} padding={2} tone="transparent" radius={2}>
                                    <Stack space={1}>
                                        <Text size={1} weight="semibold">{p.name}</Text>
                                        <Text size={0} muted>Before: {p.old}</Text>
                                        <Text size={0} style={{ color: '#10b981' }}>After: {p.new} ({p.new.length})</Text>
                                    </Stack>
                                </Card>
                            ))}
                        </Stack>
                    </Box>
                )}

                {/* Results */}
                {showResults && results.length > 0 && (
                    <Box padding={3} style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 8 }}>
                        <Stack space={2}>
                            <Flex justify="space-between" align="center">
                                <Text size={0} weight="semibold" muted>RESULTS</Text>
                                <Flex gap={2}>
                                    <Badge tone="positive"><CheckCircle2 size={12} /> {successCount}</Badge>
                                    {failCount > 0 && <Badge tone="critical"><XCircle size={12} /> {failCount}</Badge>}
                                </Flex>
                            </Flex>
                            {failCount > 0 && (
                                <Card padding={2} tone="critical" radius={2}>
                                    <Stack space={1}>
                                        {results.filter(r => !r.success).slice(0, 3).map(r => (
                                            <Text key={r.collegeId} size={0}>• {r.collegeName}: {r.error}</Text>
                                        ))}
                                    </Stack>
                                </Card>
                            )}
                        </Stack>
                    </Box>
                )}
            </Stack>
        </WidgetCard>
    )
}

import { Card, Stack, Text, Badge, Flex } from '@sanity/ui'
import { ReactNode, useEffect, useState } from 'react'

interface CollegePreviewProps {
    title?: string
    subtitle?: string
    media?: ReactNode
    lastSyncedAt?: string
    highlights?: string[]
    estYear?: number
    type?: string
    isVisible?: boolean
}

export function CollegePreview(props: CollegePreviewProps) {
    const { title, subtitle, media, lastSyncedAt, highlights, estYear, type, isVisible } = props
    const [now, setNow] = useState<number | null>(null)

    useEffect(() => {
        setNow(Date.now())
    }, [])

    const isRecent = lastSyncedAt && now ? (now - new Date(lastSyncedAt).getTime()) < 86400000 : false

    return (
        <Card padding={3}>
            <Flex align="center" gap={3}>
                {media && (
                    <div style={{ width: 50, height: 50, flexShrink: 0 }}>
                        {media}
                    </div>
                )}
                <Stack space={2} flex={1}>
                    <Flex align="center" gap={2}>
                        <Text weight="semibold" size={2}>{title}</Text>
                        {!isVisible && (
                            <Badge tone="critical" fontSize={0}>Hidden</Badge>
                        )}
                    </Flex>

                    {subtitle && <Text size={1} muted>{subtitle}</Text>}

                    <Flex gap={2} wrap="wrap">
                        {type && (
                            <Badge tone={type === 'Government' ? 'primary' : 'default'} fontSize={0}>
                                {type}
                            </Badge>
                        )}

                        {estYear && (
                            <Badge tone="positive" fontSize={0}>
                                Est. {estYear}
                            </Badge>
                        )}

                        {lastSyncedAt ? (
                            <Badge tone={isRecent ? 'positive' : 'caution'} fontSize={0}>
                                {isRecent ? 'Synced Recently' : 'Outdated'}
                            </Badge>
                        ) : (
                            <Badge tone="critical" fontSize={0}>
                                Never Synced
                            </Badge>
                        )}

                        {highlights && highlights.length > 0 && (
                            <Badge tone="default" fontSize={0}>
                                {highlights.length} highlights
                            </Badge>
                        )}
                    </Flex>
                </Stack>
            </Flex>
        </Card>
    )
}

// Custom Deploy Widget for Sanity Dashboard
// USES LOCALSTORAGE for security (Vercel webhooks are private)

'use client'

import { Stack, Text, Button, Box, TextInput, Grid, Flex, Badge, Card } from '@sanity/ui'
import { useState, useEffect } from 'react'
import { Rocket, Plus, Trash2, ExternalLink, Clock } from 'lucide-react'
import { useDeployment } from '../utils/hooks/useDeployment'
import { validateWebhookUrl, type DeployTarget } from '../utils/deployActions'
import { WidgetCard, EmptyState } from './shared'

export function CustomDeployWidget() {
    const { targets, deploying, lastDeployed, deploy, addTarget, deleteDeployTarget } = useDeployment()

    const [showAddForm, setShowAddForm] = useState(false)
    const [newTarget, setNewTarget] = useState<Partial<DeployTarget>>({
        name: '',
        url: '',
        branch: ''
    })

    const handleAddTarget = () => {
        if (!newTarget.name || !newTarget.url) {
            return
        }

        if (!validateWebhookUrl(newTarget.url)) {
            alert('Invalid webhook URL. Must be a Vercel HTTPS URL.')
            return
        }

        const target: DeployTarget = {
            id: `deploy-${Date.now()}`,
            name: newTarget.name,
            url: newTarget.url,
            branch: newTarget.branch
        }

        addTarget(target)
        setNewTarget({ name: '', url: '', branch: '' })
        setShowAddForm(false)
    }

    const [now, setNow] = useState<number | null>(null)

    useEffect(() => {
        setNow(Date.now())
    }, [])

    const formatLastDeployed = (timestamp?: number) => {
        if (!timestamp || !now) return null
        const diff = now - timestamp
        const minutes = Math.floor(diff / 60000)
        if (minutes < 1) return 'Just now'
        if (minutes < 60) return `${minutes}m ago`
        const hours = Math.floor(minutes / 60)
        if (hours < 24) return `${hours}h ago`
        const days = Math.floor(hours / 24)
        return `${days}d ago`
    }

    return (
        <WidgetCard
            title="Deploy Targets"
            icon={<Rocket size={18} />}
            iconColor="#ef4444"
            headerGradient="linear-gradient(135deg, #ef4444 0%, #dc2626 100%)"
            collapsible
            actions={
                <Button
                    mode="bleed"
                    icon={Plus}
                    text="Add"
                    onClick={() => setShowAddForm(!showAddForm)}
                    style={{ color: 'white' }}
                    fontSize={0}
                />
            }
            footer={
                <Flex align="center" gap={1}>
                    <ExternalLink size={12} style={{ opacity: 0.5 }} />
                    <Text size={0} muted>
                        Get webhook from Vercel → Settings → Deploy Hooks
                    </Text>
                </Flex>
            }
        >
            <Stack space={4}>
                {/* Add Target Form */}
                {showAddForm && (
                    <Box padding={3} style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 8 }}>
                        <Stack space={3}>
                            <Text size={1} weight="semibold">New Deploy Target</Text>

                            <TextInput
                                placeholder="Target name (e.g., Production)"
                                value={newTarget.name || ''}
                                onChange={(e) => setNewTarget(prev => ({ ...prev, name: e.currentTarget.value }))}
                                fontSize={1}
                            />

                            <TextInput
                                placeholder="Vercel webhook URL"
                                value={newTarget.url || ''}
                                onChange={(e) => setNewTarget(prev => ({ ...prev, url: e.currentTarget.value }))}
                                fontSize={1}
                            />

                            <TextInput
                                placeholder="Branch (optional, e.g., main)"
                                value={newTarget.branch || ''}
                                onChange={(e) => setNewTarget(prev => ({ ...prev, branch: e.currentTarget.value }))}
                                fontSize={1}
                            />

                            <Grid columns={2} gap={2}>
                                <Button
                                    mode="default"
                                    text="Save"
                                    onClick={handleAddTarget}
                                    tone="positive"
                                    disabled={!newTarget.name || !newTarget.url}
                                    fontSize={1}
                                />
                                <Button
                                    mode="ghost"
                                    text="Cancel"
                                    onClick={() => {
                                        setShowAddForm(false)
                                        setNewTarget({ name: '', url: '', branch: '' })
                                    }}
                                    fontSize={1}
                                />
                            </Grid>
                        </Stack>
                    </Box>
                )}

                {/* Deploy Targets List */}
                {targets.length === 0 ? (
                    <EmptyState
                        icon={<Rocket size={32} />}
                        title="No deploy targets configured"
                        description="Add a Vercel webhook URL to get started"
                    />
                ) : (
                    <Stack space={2}>
                        {targets.map(target => (
                            <Card key={target.id} padding={3} border radius={2}>
                                <Stack space={3}>
                                    <Flex justify="space-between" align="center">
                                        <Stack space={1}>
                                            <Flex align="center" gap={2}>
                                                <Text size={1} weight="semibold">{target.name}</Text>
                                                {target.branch && (
                                                    <Badge tone="primary" fontSize={0}>
                                                        {target.branch}
                                                    </Badge>
                                                )}
                                            </Flex>
                                            {lastDeployed[target.id] && (
                                                <Flex align="center" gap={1}>
                                                    <Clock size={12} style={{ opacity: 0.5 }} />
                                                    <Text size={0} muted>
                                                        Last: {formatLastDeployed(lastDeployed[target.id])}
                                                    </Text>
                                                </Flex>
                                            )}
                                        </Stack>
                                        <Button
                                            mode="ghost"
                                            icon={Trash2}
                                            onClick={() => {
                                                if (confirm(`Delete "${target.name}"?`)) {
                                                    deleteDeployTarget(target.id)
                                                }
                                            }}
                                            tone="critical"
                                            fontSize={1}
                                        />
                                    </Flex>

                                    <Button
                                        mode="default"
                                        icon={Rocket}
                                        text={deploying[target.id] ? 'Deploying...' : 'Deploy Now'}
                                        onClick={() => deploy(target)}
                                        disabled={deploying[target.id]}
                                        tone="positive"
                                        fontSize={1}
                                        style={{ width: '100%' }}
                                    />
                                </Stack>
                            </Card>
                        ))}
                    </Stack>
                )}
            </Stack>
        </WidgetCard>
    )
}

// Data Quality Widget for Sanity Dashboard
// Shows comprehensive statistics and quality metrics for college data

'use client'

import { Stack, Text, Button, Box, Badge, Flex, TextInput, Card, Grid } from '@sanity/ui'
import { useState } from 'react'
import { useRouter } from 'sanity/router'
import { BarChart3, ChevronDown, ChevronUp, Activity, Eye, EyeOff, Building2, AlertCircle, Search, RefreshCw, ArrowRight } from 'lucide-react'
import { useSanityStats } from '../utils/hooks/useSanityStats'
import { WidgetCard, StatsGrid, ProgressBar, EmptyState, LoadingSkeleton } from './shared'

type ExpandedSection = 'synced' | 'missing' | 'incomplete' | 'noHighlights' | 'missingLogo'

export function DataQualityWidget() {
    const { loading, error, data, refetch } = useSanityStats()
    const router = useRouter()
    const [expandedSection, setExpandedSection] = useState<ExpandedSection | null>(null)
    const [searchTerm, setSearchTerm] = useState('')

    const handleToggleSection = (section: ExpandedSection) => {
        setExpandedSection(prev => prev === section ? null : section)
    }

    const navigateToCollege = (id: string) => router.navigateIntent('edit', { id: id?.replace('drafts.', ''), type: 'college' })

    const filterColleges = (colleges: any[]) => {
        if (!searchTerm.trim()) return colleges
        return colleges.filter(college => college.name.toLowerCase().includes(searchTerm.toLowerCase()))
    }

    const getQualityTone = (score: number): 'positive' | 'caution' | 'critical' => {
        if (score >= 80) return 'positive'
        if (score >= 50) return 'caution'
        return 'critical'
    }

    const getQualityColor = (score: number): string => {
        if (score >= 80) return '#10b981'
        if (score >= 50) return '#f59e0b'
        return '#ef4444'
    }

    if (error) {
        return (
            <WidgetCard title="Data Quality" icon={<BarChart3 size={18} />} iconColor="#ef4444">
                <EmptyState title="Error loading data" description={error} />
                <Button text="Retry" onClick={refetch} mode="ghost" tone="critical" />
            </WidgetCard>
        )
    }

    if (!data) return null

    const { stats } = data

