            ) : (
                <Stack space={4}>
                    {/* Quality Score */}
                    <Box padding={4} style={{
                        background: `linear-gradient(135deg, ${getQualityColor(stats.qualityScore)}22, ${getQualityColor(stats.qualityScore)}11)`,
