                    {/* Overview Stats */}
                    <StatsGrid
                        columns={3}
                        stats={[
                            { label: 'Total', value: stats.total, icon: <Building2 size={14} /> },
                            { label: 'Visible', value: stats.visible, tone: 'positive', icon: <Eye size={14} /> },
                            { label: 'Hidden', value: stats.total - stats.visible, tone: 'caution', icon: <EyeOff size={14} /> }
