// Duplicate Detection Widget
// Finds and helps merge duplicate college entries

'use client'

import { Stack, Text, Button, Box, Badge, Flex, Grid, Card } from '@sanity/ui'
import { useState } from 'react'
import { useClient } from 'sanity'
import { useRouter } from 'sanity/router'
import { Copy, GitMerge, Search, AlertCircle } from 'lucide-react'
import { apiVersion } from '../env'
import { findDuplicates, groupDuplicates, mergeDuplicates, type DuplicateMatch, type DuplicateGroup } from '../utils/duplicateDetection'
import { WidgetCard, EmptyState } from './shared'

export function DuplicateDetectionWidget() {
    const client = useClient({ apiVersion })
    const router = useRouter()
    const [scanning, setScanning] = useState(false)
    const [matches, setMatches] = useState<DuplicateMatch[]>([])
    const [groups, setGroups] = useState<DuplicateGroup[]>([])
    const [merging, setMerging] = useState<Set<string>>(new Set())
    const [ignored, setIgnored] = useState<Set<string>>(new Set())

    const handleScan = async () => {
        setScanning(true)
        try {
            const duplicates = await findDuplicates(client, 70)
            setMatches(duplicates)
            setGroups(duplicates.length > 0 ? groupDuplicates(duplicates) : [])
        } catch (error) {
            console.error('Duplicate scan failed:', error)
        } finally {
            setScanning(false)
        }
    }

    const handleMerge = async (group: DuplicateGroup) => {
        const primaryId = group.suggestedPrimary
        const duplicateIds = group.colleges.filter(c => c._id !== primaryId).map(c => c._id)
        const primaryName = group.colleges.find(c => c._id === primaryId)?.name

        if (!window.confirm(`Merge ${duplicateIds.length} duplicate(s) into "${primaryName}"?\n\nThis cannot be undone!`)) return

        setMerging(prev => new Set(prev).add(primaryId))
        try {
            const result = await mergeDuplicates(client, primaryId, duplicateIds)
            if (result.success) await handleScan()
            else alert(`Merge failed: ${result.message}`)
        } catch (error) {
            alert('Merge failed')
        } finally {
            setMerging(prev => { const next = new Set(prev); next.delete(primaryId); return next })
        }
    }

    const navigateToCollege = (id: string) => router.navigateIntent('edit', { id: id?.replace('drafts.', ''), type: 'college' })

    const handleDismiss = (groupId: string) => {
        setIgnored(prev => new Set(prev).add(groupId))
    }

    const visibleGroups = groups.filter(g => !ignored.has(g.suggestedPrimary))

    return (
        <WidgetCard
            title="Duplicate Detection"
            icon={<Copy size={18} />}
            iconColor="#f59e0b"
            headerGradient="linear-gradient(135deg, #f59e0b 0%, #d97706 100%)"
            loading={scanning}
            collapsible
            actions={
                <Button
                    icon={Search}
                    onClick={handleScan}
                    disabled={scanning}
                    mode="bleed"
                    style={{ color: 'white' }}
                    title="Scan for Duplicates"
                />
            }
        >
            <Stack space={4}>
                {/* Results Summary */}
                {groups.length > 0 && (
                    <Box padding={3} style={{ background: 'rgba(245, 158, 11, 0.1)', borderRadius: 8 }}>
                        <Flex justify="space-between" align="center">
                            <Flex gap={2} align="center">
                                <AlertCircle size={16} />
                                <Text size={1} weight="semibold">{visibleGroups.length} duplicate groups</Text>
                                {ignored.size > 0 && <Text size={0} muted>({ignored.size} dismissed)</Text>}
                            </Flex>
                            <Badge tone="caution">{matches.length} matches</Badge>
                        </Flex>
                    </Box>
                )}

                {/* No Duplicates */}
                {!scanning && matches.length === 0 && groups.length === 0 && (
                    <Box padding={4} style={{ background: 'rgba(16, 185, 129, 0.1)', borderRadius: 8, textAlign: 'center' }}>
                        <Stack space={2}>
                            <Copy size={28} style={{ margin: '0 auto', color: '#10b981' }} />
                            <Text size={1} weight="semibold" style={{ color: '#10b981' }}>No duplicates found!</Text>
                            <Text size={0} muted>All entries appear unique</Text>
                        </Stack>
                    </Box>
                )}

                {/* Duplicate Groups */}
                {groups.length > 0 && (
                    <Box style={{ maxHeight: '350px', overflowY: 'auto' }}>
                        <Stack space={3}>
                            {visibleGroups.map((group, groupIdx) => {
                                const primary = group.colleges.find(c => c._id === group.suggestedPrimary)
                                const duplicates = group.colleges.filter(c => c._id !== group.suggestedPrimary)
                                const isMerging = merging.has(group.suggestedPrimary)

                                return (
                                    <Card key={groupIdx} padding={3} border tone="caution" radius={2}>
                                        <Stack space={3}>
                                            <Flex justify="space-between" align="center">
                                                <Stack space={1}>
                                                    <Text size={1} weight="semibold">Group #{groupIdx + 1}</Text>
                                                    <Badge tone="caution">{group.similarity}% similar</Badge>
                                                </Stack>
                                                <Flex gap={1}>
                                                    <Button
                                                        text="Dismiss"
                                                        onClick={() => handleDismiss(group.suggestedPrimary)}
                                                        mode="ghost"
                                                        tone="default"
                                                        fontSize={0}
                                                    />
                                                    <Button
                                                        text={isMerging ? 'Merging...' : `Merge ${duplicates.length}`}
                                                        onClick={() => handleMerge(group)}
                                                        disabled={isMerging}
                                                        icon={GitMerge}
                                                        tone="caution"
                                                        fontSize={0}
                                                    />
                                                </Flex>
                                            </Flex>

                                            {/* Primary */}
                                            {primary && (
                                                <Card padding={3} tone="positive" radius={2}>
                                                    <Flex justify="space-between" align="flex-start" gap={2}>
                                                        <Stack space={1} flex={1} style={{ minWidth: 0 }}>
                                                            <Text size={0} weight="semibold" style={{ color: '#10b981' }}>✓ Keep</Text>
                                                            <Text size={1} style={{ wordBreak: 'break-word' }}>{primary.name}</Text>
                                                            <Text size={0} muted style={{ wordBreak: 'break-word' }}>{primary.location} • {primary.type}</Text>
                                                        </Stack>
                                                        <Button text="View" onClick={() => navigateToCollege(primary._id)} mode="ghost" fontSize={0} style={{ flexShrink: 0 }} />
                                                    </Flex>
                                                </Card>
                                            )}

                                            {/* Duplicates */}
                                            <Stack space={1}>
                                                {duplicates.map(dup => (
                                                    <Card key={dup._id} padding={3} tone="transparent" border radius={2}>
                                                        <Flex justify="space-between" align="flex-start" gap={2}>
                                                            <Stack space={1} flex={1} style={{ minWidth: 0 }}>
                                                                <Text size={0} muted>✗ Delete</Text>
                                                                <Text size={1} style={{ wordBreak: 'break-word' }}>{dup.name}</Text>
                                                                <Text size={0} muted style={{ wordBreak: 'break-word' }}>{dup.location}</Text>
                                                            </Stack>
                                                            <Button text="View" onClick={() => navigateToCollege(dup._id)} mode="ghost" fontSize={0} style={{ flexShrink: 0 }} />
                                                        </Flex>
                                                    </Card>
                                                ))}
                                            </Stack>
                                        </Stack>
                                    </Card>
                                )
                            })}
                        </Stack>
                    </Box>
                )}
            </Stack>
        </WidgetCard>
    )
}

// Export Templates Widget
// Create and manage custom export templates

'use client'

import { Stack, Text, Button, Box, Badge, Flex, TextInput, Select, Checkbox, Grid } from '@sanity/ui'
import { useState, useEffect } from 'react'
import { useClient } from 'sanity'
import { Download, Plus, Trash2, Save, FileSpreadsheet } from 'lucide-react'
import { apiVersion } from '../env'
import {
    exportWithTemplate,
    saveTemplate,
    loadTemplates,
    deleteTemplate,
    AVAILABLE_FIELDS,
    type ExportTemplate
} from '../utils/exportTemplates'
import { WidgetCard } from './shared'

export function ExportTemplatesWidget() {
    const client = useClient({ apiVersion })
    const [templates, setTemplates] = useState<ExportTemplate[]>([])
    const [selectedTemplate, setSelectedTemplate] = useState<string>('')
    const [newTemplateName, setNewTemplateName] = useState('')
    const [selectedFields, setSelectedFields] = useState<string[]>([])
    const [exportFormat, setExportFormat] = useState<'json' | 'csv'>('csv')
    const [filter, setFilter] = useState<'all' | 'visible' | 'hidden'>('all')
    const [exporting, setExporting] = useState(false)
    const [creating, setCreating] = useState(false)

    useEffect(() => { loadSavedTemplates() }, [])

    const loadSavedTemplates = () => {
        const saved = loadTemplates()
        setTemplates(saved)
        if (selectedFields.length === 0) {
            setSelectedFields(AVAILABLE_FIELDS.filter(f => f.selected).map(f => f.key))
        }
    }

    const handleCreateTemplate = () => {
        if (!newTemplateName.trim()) return
        const template: ExportTemplate = { name: newTemplateName.trim(), fields: selectedFields, format: exportFormat }
        saveTemplate(template)
        loadSavedTemplates()
        setNewTemplateName('')
        setCreating(false)
    }

    const handleDeleteTemplate = (templateName: string) => {
        if (window.confirm(`Delete template "${templateName}"?`)) {
            deleteTemplate(templateName)
            loadSavedTemplates()
            if (selectedTemplate === templateName) setSelectedTemplate('')
        }
    }

    const handleLoadTemplate = (templateName: string) => {
        const template = templates.find(t => t.name === templateName)
        if (template) {
            setSelectedFields(template.fields)
            if (template.format === 'json' || template.format === 'csv') setExportFormat(template.format)
            setSelectedTemplate(templateName)
        }
    }

    const handleExport = async () => {
        if (selectedFields.length === 0) return alert('Select at least one field')
        setExporting(true)
        try {
            const template: ExportTemplate = { name: selectedTemplate || 'custom-export', fields: selectedFields, format: exportFormat }
            const result = await exportWithTemplate(client, template, filter)
            alert(result.success ? result.message : `Export failed: ${result.message}`)
        } catch (error) {
            alert('Export failed')
            console.error(error)
        } finally {
            setExporting(false)
        }
    }

    const toggleField = (fieldKey: string) => {
        setSelectedFields(prev => prev.includes(fieldKey) ? prev.filter(k => k !== fieldKey) : [...prev, fieldKey])
    }

    return (
        <WidgetCard
            title="Export Templates"
            icon={<FileSpreadsheet size={18} />}
            iconColor="#3b82f6"
            headerGradient="linear-gradient(135deg, #3b82f6 0%, #1d4ed8 100%)"
            collapsible
        >
            <Stack space={4}>
                {/* Saved Templates */}
                {templates.length > 0 && (
                    <Box padding={3} style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 8 }}>
                        <Stack space={2}>
                            <Text size={0} weight="semibold" muted>SAVED TEMPLATES</Text>
                            <Stack space={1}>
                                {templates.map(template => (
                                    <Flex key={template.name} justify="space-between" align="center">
                                        <Button
                                            text={template.name}
                                            mode={selectedTemplate === template.name ? 'default' : 'ghost'}
                                            onClick={() => handleLoadTemplate(template.name)}
                                            fontSize={1}
                                            style={{ flex: 1, justifyContent: 'flex-start' }}
                                        />
                                        <Flex gap={1}>
                                            <Badge tone="primary" fontSize={0}>{template.format.toUpperCase()}</Badge>
                                            <Badge tone="default" fontSize={0}>{template.fields.length} fields</Badge>
                                            <Button icon={Trash2} mode="bleed" tone="critical" onClick={() => handleDeleteTemplate(template.name)} fontSize={0} />
                                        </Flex>
                                    </Flex>
                                ))}
                            </Stack>
                        </Stack>
                    </Box>
                )}

                {/* Field Selection */}
                <Box padding={3} style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 8 }}>
                    <Stack space={2}>
                        <Text size={0} weight="semibold" muted>SELECT FIELDS</Text>
                        <Box style={{ maxHeight: '150px', overflowY: 'auto' }}>
                            <Stack space={1}>
                                {AVAILABLE_FIELDS.map(field => (
                                    <Flex key={field.key} align="center" gap={2}>
                                        <Checkbox checked={selectedFields.includes(field.key)} onChange={() => toggleField(field.key)} />
                                        <Text size={1}>{field.label}</Text>
                                    </Flex>
                                ))}
                            </Stack>
                        </Box>
                        <Text size={0} muted>{selectedFields.length} field{selectedFields.length !== 1 ? 's' : ''} selected</Text>
                    </Stack>
                </Box>

                {/* Export Options */}
                <Grid columns={2} gap={2}>
                    <Stack space={1}>
                        <Text size={0} muted>FORMAT</Text>
                        <Select value={exportFormat} onChange={(e) => setExportFormat(e.currentTarget.value as 'json' | 'csv')} fontSize={1}>
                            <option value="csv">CSV</option>
                            <option value="json">JSON</option>
                        </Select>
                    </Stack>
                    <Stack space={1}>
                        <Text size={0} muted>FILTER</Text>
                        <Select value={filter} onChange={(e) => setFilter(e.currentTarget.value as any)} fontSize={1}>
                            <option value="all">All</option>
                            <option value="visible">Visible</option>
                            <option value="hidden">Hidden</option>
                        </Select>
                    </Stack>
                </Grid>

                {/* Actions */}
                <Flex gap={2}>
                    <Button
                        text={exporting ? 'Exporting...' : 'Export'}
                        onClick={handleExport}
                        disabled={exporting || selectedFields.length === 0}
                        tone="positive"
                        icon={Download}
                        fontSize={1}
                        style={{ flex: 1 }}
                    />
                    <Button text="Save Template" onClick={() => setCreating(true)} mode="ghost" icon={Plus} fontSize={1} />
                </Flex>

                {/* Create Template */}
                {creating && (
                    <Box padding={3} style={{ background: 'rgba(59, 130, 246, 0.1)', borderRadius: 8 }}>
                        <Stack space={2}>
                            <Text size={0} weight="semibold" muted>SAVE TEMPLATE</Text>
                            <TextInput placeholder="Template name..." value={newTemplateName} onChange={(e) => setNewTemplateName(e.currentTarget.value)} fontSize={1} />
                            <Flex gap={2}>
                                <Button text="Save" onClick={handleCreateTemplate} disabled={!newTemplateName.trim()} tone="positive" icon={Save} fontSize={1} />
                                <Button text="Cancel" onClick={() => { setCreating(false); setNewTemplateName('') }} mode="ghost" fontSize={1} />
                            </Flex>
                        </Stack>
                    </Box>
                )}
            </Stack>
        </WidgetCard>
    )
}

// Quick Actions Panel Widget
// Provides fast access to common tasks and recent actions

'use client'

import { Stack, Text, Button, Box, Badge, Flex, Grid, TextInput } from '@sanity/ui'
import { useState, useEffect } from 'react'
import { useClient } from 'sanity'
import { useRouter } from 'sanity/router'
import {
    Zap, Search, Plus, Eye, EyeOff, RefreshCw, Download,
    CheckCircle, Star, Clock, ArrowRight
} from 'lucide-react'
import { apiVersion } from '../env'
import { WidgetCard } from './shared'

interface QuickAction {
    id: string
    label: string
    icon: any
    action: () => void
    tone?: 'default' | 'primary' | 'positive' | 'caution' | 'critical'
}

interface RecentItem {
    _id: string
    _type: string
    name: string
    _updatedAt: string
}

export function QuickActionsWidget() {
    const client = useClient({ apiVersion })
    const router = useRouter()
    const [searchQuery, setSearchQuery] = useState('')
    const [recentItems, setRecentItems] = useState<RecentItem[]>([])
    const [favorites, setFavorites] = useState<string[]>([])
    const [loading, setLoading] = useState(false)

    useEffect(() => {
        fetchRecentItems()
        loadFavorites()
    }, [])

    const fetchRecentItems = async () => {
        try {
            const items = await client.fetch(`
                *[_type == "college"] | order(_updatedAt desc) [0...5] {
                    _id, _type, name, _updatedAt
                }
            `)
            setRecentItems(items)
        } catch (error) {
            console.error('Failed to fetch recent items:', error)
        }
    }

    const loadFavorites = () => {
        try {
            const stored = localStorage.getItem('sanity-favorites')
            if (stored) {
                setFavorites(JSON.parse(stored))
            }
        } catch (error) {
            console.error('Failed to load favorites:', error)
        }
    }

    const toggleFavorite = (id: string) => {
        const newFavorites = favorites.includes(id)
            ? favorites.filter(f => f !== id)
            : [...favorites, id]
        setFavorites(newFavorites)
        localStorage.setItem('sanity-favorites', JSON.stringify(newFavorites))
    }

    const navigateToDocument = (id: string, type: string = 'college') => {
        router.navigateIntent('edit', { id: id?.replace('drafts.', ''), type })
    }

    const handleSearch = async () => {
        if (!searchQuery.trim()) return
        setLoading(true)
        try {
            const searchTerm = `${searchQuery}*`
            const results = await client.fetch(`
                *[_type == "college" && name match $term] | order(name asc) [0...10] {
                    _id, _type, name, _updatedAt
                }
            `, { term: searchTerm })
            setRecentItems(results)
        } catch (error) {
            console.error('Search failed:', error)
        } finally {
            setLoading(false)
        }
    }

    const quickActions: QuickAction[] = [
        {
            id: 'new-college',
            label: 'New College',
            icon: Plus,
            action: () => router.navigateIntent('create', { type: 'college' }),
            tone: 'positive'
        },
        {
            id: 'view-all',
            label: 'All Colleges',
            icon: Eye,
            action: () => router.navigateIntent('create', { type: 'college' }),
            tone: 'primary'
        },
        {
            id: 'hidden-colleges',
            label: 'Hidden',
            icon: EyeOff,
            action: async () => {
                const hidden = await client.fetch(`
                    *[_type == "college" && isVisible == false] | order(name asc) [0...10] {
                        _id, _type, name, _updatedAt
                    }
                `)
                setRecentItems(hidden)
            },
            tone: 'caution'
        },
        {
            id: 'refresh',
            label: 'Refresh',
            icon: RefreshCw,
            action: () => {
                fetchRecentItems()
                setSearchQuery('')
            }
        },
        {
            id: 'export-json',
            label: 'Export',
            icon: Download,
            action: async () => {
                const data = await client.fetch(`*[_type == "college"]`)
                const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' })
                const url = URL.createObjectURL(blob)
                const a = document.createElement('a')
                a.href = url
                a.download = `colleges-${new Date().toISOString().split('T')[0]}.json`
                a.click()
                URL.revokeObjectURL(url)
            },
            tone: 'primary'
        },
        {
            id: 'validation',
            label: 'Validate',
            icon: CheckCircle,
            action: () => console.log('Validation triggered'),
            tone: 'positive'
        }
    ]

    const formatTime = (dateString: string) => {
        const date = new Date(dateString)
        const now = new Date()
        const diff = now.getTime() - date.getTime()
        const minutes = Math.floor(diff / 60000)
        const hours = Math.floor(diff / 3600000)
        const days = Math.floor(diff / 86400000)

        if (minutes < 1) return 'Just now'
        if (minutes < 60) return `${minutes}m ago`
        if (hours < 24) return `${hours}h ago`
        if (days < 7) return `${days}d ago`
        return date.toLocaleDateString()
    }

    return (
        <WidgetCard
            title="Quick Actions"
            icon={<Zap size={18} />}
            iconColor="#f59f00"
            headerGradient="linear-gradient(135deg, #f59f00 0%, #d97706 100%)"
            collapsible
            compact
        >
            <Stack space={4}>
                {/* Search */}
                <Flex gap={2}>
                    <Box flex={1}>
                        <TextInput
                            icon={Search}
                            placeholder="Search colleges..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.currentTarget.value)}
                            onKeyPress={(e) => e.key === 'Enter' && handleSearch()}
                            fontSize={1}
                        />
                    </Box>
                    <Button
                        icon={Search}
                        onClick={handleSearch}
                        disabled={loading || !searchQuery.trim()}
                        mode="ghost"
                    />
                </Flex>

                {/* Quick Action Buttons */}
                <Grid columns={3} gap={2}>
                    {quickActions.map(action => (
                        <Button
                            key={action.id}
                            text={action.label}
                            icon={action.icon}
                            onClick={action.action}
                            mode="ghost"
                            tone={action.tone}
                            fontSize={0}
                            style={{ justifyContent: 'flex-start' }}
                        />
                    ))}
                </Grid>

                {/* Recent Items */}
                <Box padding={3} style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 8 }}>
                    <Stack space={2}>
                        <Flex justify="space-between" align="center">
                            <Flex align="center" gap={2}>
                                <Clock size={14} style={{ opacity: 0.5 }} />
                                <Text size={1} weight="semibold">
                                    {searchQuery ? 'Search Results' : 'Recent'}
                                </Text>
                            </Flex>
                            {recentItems.length > 0 && (
                                <Badge tone="default">{recentItems.length}</Badge>
                            )}
                        </Flex>

                        {loading ? (
                            <Text size={1} muted>Searching...</Text>
                        ) : recentItems.length > 0 ? (
                            <Stack space={1}>
                                {recentItems.map(item => (
                                    <Flex key={item._id} justify="space-between" align="center">
                                        <Button
                                            mode="bleed"
                                            onClick={() => navigateToDocument(item._id, item._type)}
                                            style={{ flex: 1, justifyContent: 'flex-start' }}
                                        >
                                            <Flex align="center" gap={2} style={{ width: '100%' }}>
                                                <Text size={1} style={{ flex: 1 }}>{item.name}</Text>
                                                <Text size={0} muted>{formatTime(item._updatedAt)}</Text>
                                            </Flex>
                                        </Button>
                                        <Button
                                            icon={Star}
                                            mode="bleed"
                                            tone={favorites.includes(item._id) ? 'caution' : 'default'}
                                            onClick={() => toggleFavorite(item._id)}
                                            style={{ opacity: favorites.includes(item._id) ? 1 : 0.3 }}
                                        />
                                    </Flex>
                                ))}
                            </Stack>
                        ) : (
                            <Text size={1} muted>
                                {searchQuery ? 'No results found' : 'No recent items'}
                            </Text>
                        )}
                    </Stack>
                </Box>

                {/* Favorites */}
                {favorites.length > 0 && recentItems.filter(item => favorites.includes(item._id)).length > 0 && (
                    <Box padding={3} style={{ background: 'rgba(245, 158, 11, 0.1)', borderRadius: 8 }}>
                        <Stack space={2}>
                            <Flex align="center" gap={2}>
                                <Star size={14} style={{ color: '#f59f00' }} />
                                <Text size={1} weight="semibold">Favorites</Text>
                            </Flex>
                            <Stack space={1}>
                                {recentItems
                                    .filter(item => favorites.includes(item._id))
                                    .map(item => (
                                        <Button
                                            key={item._id}
                                            mode="bleed"
                                            onClick={() => navigateToDocument(item._id, item._type)}
                                            style={{ justifyContent: 'flex-start' }}
                                        >
                                            <Flex align="center" gap={2}>
                                                <ArrowRight size={12} />
                                                <Text size={1}>{item.name}</Text>
                                            </Flex>
                                        </Button>
                                    ))
                                }
                            </Stack>
                        </Stack>
                    </Box>
                )}
            </Stack>
        </WidgetCard>
    )
}

// SEO Analyzer Widget
// Analyzes and scores SEO quality of college content

'use client'

import { Stack, Text, Button, Box, Badge, Flex, Grid, Select, Card } from '@sanity/ui'
import { useState, useEffect } from 'react'
import { useClient } from 'sanity'
import { useRouter } from 'sanity/router'
import { Search, AlertTriangle, CheckCircle, XCircle, RefreshCw } from 'lucide-react'
import { apiVersion } from '../env'
import { WidgetCard, StatsGrid, EmptyState } from './shared'

interface SeoAnalysis {
    _id: string
    name: string
    slug?: { current: string }
    description?: string
    isVisible: boolean
    logo?: any
    coverImage?: any
    website?: string
    highlights?: string[]
    score: number
    issues: SeoIssue[]
}

interface SeoIssue {
    type: 'error' | 'warning' | 'info'
    message: string
    field: string
    suggestion?: string
}

interface SeoStats {
    total: number
    excellent: number
    good: number
    fair: number
    poor: number
    avgScore: number
}

export function SeoAnalyzerWidget() {
    const client = useClient({ apiVersion })
    const router = useRouter()
    const [analyses, setAnalyses] = useState<SeoAnalysis[]>([])
    const [stats, setStats] = useState<SeoStats | null>(null)
    const [loading, setLoading] = useState(true)
    const [filter, setFilter] = useState<'all' | 'visible' | 'hidden' | 'excellent' | 'good' | 'poor' | 'critical' | 'missing-desc'>('all')
    const [sortBy, setSortBy] = useState<'score' | 'name' | 'score-desc'>('score')

    useEffect(() => {
        analyzeContent()
    }, [])

    const analyzeContent = async () => {
        setLoading(true)
        try {
            const colleges = await client.fetch(`
                *[_type == "college"] {
                    _id, name, slug, description, isVisible,
                    logo, coverImage, website, highlights
                }
            `)

            const analyzed = colleges.map(analyzeCollege)
            const scores = analyzed.map((a: SeoAnalysis) => a.score)
            const newStats: SeoStats = {
                total: analyzed.length,
                excellent: analyzed.filter((a: SeoAnalysis) => a.score >= 90).length,
                good: analyzed.filter((a: SeoAnalysis) => a.score >= 70 && a.score < 90).length,
                fair: analyzed.filter((a: SeoAnalysis) => a.score >= 50 && a.score < 70).length,
                poor: analyzed.filter((a: SeoAnalysis) => a.score < 50).length,
                avgScore: scores.length > 0
                    ? Math.round(scores.reduce((a: number, b: number) => a + b, 0) / scores.length)
                    : 0
            }

            setAnalyses(analyzed)
            setStats(newStats)
        } catch (error) {
            console.error('SEO analysis failed:', error)
        } finally {
            setLoading(false)
        }
    }

    const analyzeCollege = (college: any): SeoAnalysis => {
        const issues: SeoIssue[] = []
        let score = 100

        // Meta Description
        if (!college.description) {
            issues.push({ type: 'error', field: 'description', message: 'Missing description' })
            score -= 25
        } else if (college.description.length < 100) {
            issues.push({ type: 'warning', field: 'description', message: 'Description too short' })
            score -= 10
        }

        // Slug
        if (!college.slug?.current) {
            issues.push({ type: 'error', field: 'slug', message: 'Missing URL slug' })
            score -= 15
        }

        // Images
        if (!college.logo) {
            issues.push({ type: 'error', field: 'logo', message: 'Missing logo' })
            score -= 15
        }

        // Website
        if (college.website && !college.website.startsWith('https://')) {
            issues.push({ type: 'warning', field: 'website', message: 'Not using HTTPS' })
            score -= 3
        }

        // Highlights
        if (!college.highlights || college.highlights.length === 0) {
            issues.push({ type: 'warning', field: 'highlights', message: 'No highlights' })
            score -= 10
        }

        return { ...college, score: Math.max(0, score), issues }
    }

    const getScoreColor = (score: number): string => {
        if (score >= 90) return '#10b981'
        if (score >= 70) return '#3b82f6'
        if (score >= 50) return '#f59e0b'
        return '#ef4444'
    }

    const getScoreTone = (score: number): 'positive' | 'primary' | 'caution' | 'critical' => {
        if (score >= 90) return 'positive'
        if (score >= 70) return 'primary'
        if (score >= 50) return 'caution'
        return 'critical'
    }

    const navigateToCollege = (id: string) => {
        router.navigateIntent('edit', { id: id?.replace('drafts.', ''), type: 'college' })
    }

    const filteredAnalyses = analyses
        .filter(a => {
            if (filter === 'visible') return a.isVisible
            if (filter === 'hidden') return !a.isVisible
            if (filter === 'excellent') return a.score >= 90
            if (filter === 'good') return a.score >= 70 && a.score < 90
            if (filter === 'poor') return a.score >= 50 && a.score < 70
            if (filter === 'critical') return a.score < 50
            if (filter === 'missing-desc') return !a.description
            return true
        })
        .sort((a, b) => {
            if (sortBy === 'score') return a.score - b.score
            if (sortBy === 'score-desc') return b.score - a.score
            return a.name.localeCompare(b.name)
        })

    return (
        <WidgetCard
            title="SEO Analyzer"
            icon={<Search size={18} />}
            iconColor="#10b981"
            headerGradient="linear-gradient(135deg, #10b981 0%, #059669 100%)"
            loading={loading}
            collapsible
            actions={
                <Button
                    icon={RefreshCw}
                    onClick={analyzeContent}
                    disabled={loading}
                    mode="bleed"
                    style={{ color: 'white' }}
                />
            }
            footer={stats && (
                <Text size={0} muted style={{ textAlign: 'center' }}>
                    {analyses.filter(a => a.score >= 70).length}/{analyses.length} with good SEO
                </Text>
            )}
        >
            <Stack space={4}>
                {/* Stats */}
                {stats && (
                    <StatsGrid
                        columns={5}
                        stats={[
                            { label: 'Average', value: `${stats.avgScore}%`, tone: getScoreTone(stats.avgScore) as any },
                            { label: '90+', value: stats.excellent, tone: 'positive' },
                            { label: '70-89', value: stats.good, tone: 'primary' },
                            { label: '50-69', value: stats.fair, tone: 'caution' },
                            { label: '<50', value: stats.poor, tone: 'critical' }
                        ]}
                    />
                )}

                {/* Filters */}
                <Flex gap={2} wrap="wrap">
                    <Box flex={1} style={{ minWidth: '200px' }}>
                        <Select
                            value={filter}
                            onChange={(e) => setFilter(e.currentTarget.value as any)}
                            fontSize={1}
                        >
                            <option value="all">All ({analyses.length})</option>
                            <option value="visible">Visible Only</option>
                            <option value="hidden">Hidden Only</option>
                            <option value="excellent">Excellent (90+)</option>
                            <option value="good">Good (70-89)</option>
                            <option value="poor">Fair (50-69)</option>
                            <option value="critical">Poor (&lt;50)</option>
                            <option value="missing-desc">Missing Description</option>
                        </Select>
                    </Box>
                    <Box flex={1} style={{ minWidth: '200px' }}>
                        <Select
                            value={sortBy}
                            onChange={(e) => setSortBy(e.currentTarget.value as any)}
                            fontSize={1}
                        >
                            <option value="score">Score (Low → High)</option>
                            <option value="score-desc">Score (High → Low)</option>
                            <option value="name">Name (A → Z)</option>
                        </Select>
                    </Box>
                </Flex>

                {/* Results */}
                <Box style={{ maxHeight: '300px', overflowY: 'auto' }}>
                    {filteredAnalyses.length > 0 ? (
                        <Stack space={2}>
                            {filteredAnalyses.map(analysis => (
                                <Card key={analysis._id} padding={3} border radius={2}>
                                    <Stack space={2}>
                                        <Flex justify="space-between" align="center">
                                            <Stack space={1}>
                                                <Text size={1} weight="semibold">{analysis.name}</Text>
                                                <Flex gap={1}>
                                                    <Badge tone={getScoreTone(analysis.score)}>{analysis.score}%</Badge>
                                                    {analysis.isVisible && <Badge tone="positive" fontSize={0}>Visible</Badge>}
                                                </Flex>
                                            </Stack>
                                            <Button text="Fix" mode="ghost" onClick={() => navigateToCollege(analysis._id)} fontSize={0} />
                                        </Flex>
                                        {analysis.issues.length > 0 && (
                                            <Stack space={1}>
                                                {analysis.issues.map((issue, idx) => (
                                                    <Flex key={idx} align="center" gap={2}>
                                                        {issue.type === 'error' && <XCircle size={12} style={{ color: '#ef4444' }} />}
                                                        {issue.type === 'warning' && <AlertTriangle size={12} style={{ color: '#f59e0b' }} />}
                                                        {issue.type === 'info' && <CheckCircle size={12} style={{ color: '#3b82f6' }} />}
                                                        <Text size={0} muted>{issue.message}</Text>
                                                    </Flex>
                                                ))}
                                            </Stack>
                                        )}
                                    </Stack>
                                </Card>
                            ))}
                        </Stack>
                    ) : (
                        <EmptyState title="No results" description="Try changing the filter" />
                    )}
                </Box>
            </Stack>
        </WidgetCard>
    )
}

// Smart Validation Widget
// Provides intelligent validation with auto-fix suggestions

'use client'

import { Stack, Text, Button, Box, Badge, Flex, Card } from '@sanity/ui'
import { useState } from 'react'
import { useClient } from 'sanity'
import { useRouter } from 'sanity/router'
import { CheckCircle2, AlertTriangle, Info, Wand2, RefreshCw } from 'lucide-react'
import { apiVersion } from '../env'
import { validateColleges, autoFixIssues, type ValidationResult } from '../utils/smartValidation'
import { WidgetCard, EmptyState } from './shared'

export function SmartValidationWidget() {
    const client = useClient({ apiVersion })
    const router = useRouter()
    const [validating, setValidating] = useState(false)
    const [results, setResults] = useState<ValidationResult[]>([])
    const [fixing, setFixing] = useState<Set<string>>(new Set())

    const handleValidate = async () => {
        setValidating(true)
        try {
            const validationResults = await validateColleges(client)
            const withIssues = validationResults.filter(r => r.issues.length > 0)
            setResults(withIssues.sort((a, b) => a.score - b.score))
        } catch (error) {
            console.error('Validation failed:', error)
        } finally {
            setValidating(false)
        }
    }

    const handleAutoFix = async (result: ValidationResult) => {
        setFixing(prev => new Set(prev).add(result.collegeId))
        try {
            const fixResult = await autoFixIssues(client, result.collegeId, result.issues)
            if (fixResult.fixed > 0) await handleValidate()
        } catch (error) {
            console.error('Auto-fix failed:', error)
        } finally {
            setFixing(prev => { const next = new Set(prev); next.delete(result.collegeId); return next })
        }
    }

    const navigateToCollege = (id: string) => router.navigateIntent('edit', { id: id?.replace('drafts.', ''), type: 'college' })

    const getSeverityIcon = (severity: string) => {
        if (severity === 'error') return <AlertTriangle size={12} style={{ color: '#ef4444' }} />
        if (severity === 'warning') return <AlertTriangle size={12} style={{ color: '#f59e0b' }} />
        return <Info size={12} style={{ color: '#3b82f6' }} />
    }

    const getSeverityTone = (severity: string): 'critical' | 'caution' | 'primary' => {
        if (severity === 'error') return 'critical'
        if (severity === 'warning') return 'caution'
        return 'primary'
    }

    const errorCount = results.reduce((sum, r) => sum + r.issues.filter(i => i.severity === 'error').length, 0)
    const warningCount = results.reduce((sum, r) => sum + r.issues.filter(i => i.severity === 'warning').length, 0)

    return (
        <WidgetCard
            title="Smart Validation"
            icon={<CheckCircle2 size={18} />}
            iconColor="#f59e0b"
            headerGradient="linear-gradient(135deg, #f59e0b 0%, #d97706 100%)"
            loading={validating}
            collapsible
            actions={
                <Button
                    icon={RefreshCw}
                    onClick={handleValidate}
                    disabled={validating}
                    mode="bleed"
                    style={{ color: 'white' }}
                    title="Validate"
                />
            }
        >
            <Stack space={4}>
                {/* Results Summary */}
                {results.length > 0 && (
                    <Flex gap={2} wrap="wrap">
                        <Badge tone="default">{results.length} with issues</Badge>
                        <Badge tone="critical">{errorCount} errors</Badge>
                        <Badge tone="caution">{warningCount} warnings</Badge>
                    </Flex>
                )}

                {/* No Issues */}
                {!validating && results.length === 0 && (
                    <Box padding={4} style={{ background: 'rgba(16, 185, 129, 0.1)', borderRadius: 8, textAlign: 'center' }}>
                        <Stack space={2}>
                            <CheckCircle2 size={28} style={{ margin: '0 auto', color: '#10b981' }} />
                            <Text size={1} weight="semibold" style={{ color: '#10b981' }}>All validated!</Text>
                            <Text size={0} muted>No issues found</Text>
                        </Stack>
                    </Box>
                )}

                {/* Results List */}
                {results.length > 0 && (
                    <Box style={{ maxHeight: '300px', overflowY: 'auto' }}>
                        <Stack space={2}>
                            {results.map(result => {
                                const autoFixableCount = result.issues.filter(i => i.autoFixable).length
                                const isFixing = fixing.has(result.collegeId)

                                return (
                                    <Card key={result.collegeId} padding={3} border radius={2}>
                                        <Stack space={2}>
                                            <Flex justify="space-between" align="center">
                                                <Stack space={1}>
                                                    <Text size={1} weight="semibold">{result.collegeName}</Text>
                                                    <Flex gap={2} align="center">
                                                        <Badge tone={result.score >= 80 ? 'positive' : result.score >= 50 ? 'caution' : 'critical'}>
                                                            {result.score}/100
                                                        </Badge>
                                                        <Text size={0} muted>{result.issues.length} issues</Text>
                                                    </Flex>
                                                </Stack>
                                                <Flex gap={1}>
                                                    {autoFixableCount > 0 && (
                                                        <Button
                                                            text={isFixing ? '...' : `Fix ${autoFixableCount}`}
                                                            onClick={() => handleAutoFix(result)}
                                                            disabled={isFixing}
                                                            icon={Wand2}
                                                            mode="ghost"
                                                            tone="positive"
                                                            fontSize={0}
                                                        />
                                                    )}
                                                    <Button text="Edit" onClick={() => navigateToCollege(result.collegeId)} mode="ghost" fontSize={0} />
                                                </Flex>
                                            </Flex>
                                            <Stack space={1}>
                                                {result.issues.slice(0, 3).map((issue, idx) => (
                                                    <Flex key={idx} gap={2} align="center">
                                                        {getSeverityIcon(issue.severity)}
                                                        <Text size={0} muted>{issue.field}: {issue.message}</Text>
                                                    </Flex>
                                                ))}
                                                {result.issues.length > 3 && <Text size={0} muted>+{result.issues.length - 3} more</Text>}
                                            </Stack>
                                        </Stack>
                                    </Card>
                                )
                            })}
                        </Stack>
                    </Box>
                )}
            </Stack>
        </WidgetCard>
    )
}

// Dashboard Tabs - Tabbed navigation for organized widget display
// Groups 16 widgets into 5 logical categories

'use client'

import { Card, Stack, Flex, Text, Box } from '@sanity/ui'
import { useState, useEffect, ReactNode, lazy, Suspense } from 'react'
import {
    LayoutDashboard, ShieldCheck, Wrench, Database, Rocket,
    BarChart3, Zap, Clock, CheckCircle, Search, Link, Users,
    Layers, Eye, FileText, Upload, Download, Shield, RefreshCw
} from 'lucide-react'

// Tab configuration
interface TabConfig {
    id: string
    label: string
    icon: any
    color: string
    description: string
}

const TABS: TabConfig[] = [
    {
        id: 'overview',
        label: 'Overview',
        icon: LayoutDashboard,
        color: '#6366f1',
        description: 'Analytics, quick actions, and activity'
    },
    {
        id: 'quality',
        label: 'Quality',
        icon: ShieldCheck,
        color: '#10b981',
        description: 'Data health and validation tools'
    },
    {
        id: 'operations',
        label: 'Operations',
        icon: Wrench,
        color: '#f59e0b',
        description: 'Bulk actions and content management'
    },
    {
        id: 'data',
        label: 'Data',
        icon: Database,
        color: '#3b82f6',
        description: 'Import, export, and backup'
    },
    {
        id: 'deploy',
        label: 'Deploy',
        icon: Rocket,
        color: '#ef4444',
        description: 'Publishing and deployment'
    }
]

// Widget mapping to tabs
const TAB_WIDGETS: Record<string, string[]> = {
    overview: ['analytics', 'quick-actions', 'activity-log'],
    quality: ['data-quality', 'smart-validation', 'seo-analyzer', 'link-checker', 'duplicate-detection'],
    operations: ['batch-operations', 'visibility', 'bulk-seo', 'bulk-media-upload'],
    data: ['export-templates', 'backup-restore'],
    deploy: ['deploy-production', 'actions']
}

interface DashboardTabsProps {
    children: ReactNode
    widgetMap: Record<string, ReactNode>
}

export function DashboardTabs({ widgetMap }: { widgetMap: Record<string, ReactNode> }) {
    const [activeTab, setActiveTab] = useState<string>(() => {
        if (typeof window !== 'undefined') {
            return localStorage.getItem('sanity-dashboard-tab') || 'overview'
        }
        return 'overview'
    })

    useEffect(() => {
        localStorage.setItem('sanity-dashboard-tab', activeTab)
    }, [activeTab])

    const activeTabConfig = TABS.find(t => t.id === activeTab)
    const activeWidgets = TAB_WIDGETS[activeTab] || []

    return (
        <Stack space={4}>
            {/* Tab Navigation */}
            <Card padding={2} radius={3} style={{ background: 'rgba(255, 255, 255, 0.02)' }}>
                <Flex gap={1} wrap="wrap">
                    {TABS.map(tab => {
                        const Icon = tab.icon
                        const isActive = activeTab === tab.id
                        const widgetCount = TAB_WIDGETS[tab.id]?.length || 0

                        return (
                            <Box
                                key={tab.id}
                                as="button"
                                padding={3}
                                style={{
                                    border: 'none',
                                    background: isActive ? tab.color : 'transparent',
                                    color: isActive ? 'white' : 'inherit',
                                    borderRadius: 8,
                                    cursor: 'pointer',
                                    transition: 'all 0.15s ease',
                                    display: 'flex',
                                    alignItems: 'center',
                                    gap: 8,
                                    flex: 1,
                                    minWidth: 'fit-content',
                                    justifyContent: 'center'
                                }}
                                onClick={() => setActiveTab(tab.id)}
                            >
                                <Icon size={16} />
                                <Text
                                    size={1}
                                    weight={isActive ? 'semibold' : 'regular'}
                                    style={{ color: 'inherit' }}
                                >
                                    {tab.label}
                                </Text>
                                <Box
                                    style={{
                                        background: isActive ? 'rgba(255,255,255,0.2)' : 'rgba(255,255,255,0.1)',
                                        padding: '2px 6px',
                                        borderRadius: 10,
                                        fontSize: 10,
                                        fontWeight: 600
                                    }}
                                >
                                    {widgetCount}
                                </Box>
                            </Box>
                        )
                    })}
                </Flex>
            </Card>

            {/* Tab Description */}
            <Flex align="center" gap={2} style={{ opacity: 0.6 }}>
                {activeTabConfig && (
                    <>
                        <activeTabConfig.icon size={14} />
                        <Text size={0}>{activeTabConfig.description}</Text>
                    </>
                )}
            </Flex>

            {/* Tab Content - Grid of widgets */}
            <Box
                key={activeTab}
                style={{
                    animation: 'tab-enter 0.25s ease'
                }}
            >
                <div
                    style={{
                        display: 'grid',
                        gridTemplateColumns: 'repeat(auto-fit, minmax(350px, 1fr))',
                        gap: 16
                    }}
                >
                    {activeWidgets.map(widgetId => {
                        const widget = widgetMap[widgetId]
                        if (!widget) return null

                        return (
                            <Box key={widgetId}>
                                {widget}
                            </Box>
                        )
                    })}
                </div>
            </Box>

            {/* CSS Animation */}
            <style>{`
                @keyframes tab-enter {
                    from {
                        opacity: 0;
                        transform: translateY(8px);
                    }
                    to {
                        opacity: 1;
                        transform: translateY(0);
                    }
                }
            `}</style>
        </Stack>
    )
}

// Tab Panel wrapper for individual tabs
interface TabPanelProps {
    id: string
    activeTab: string
    children: ReactNode
}

export function TabPanel({ id, activeTab, children }: TabPanelProps) {
    if (id !== activeTab) return null

    return (
        <Box style={{ animation: 'tab-enter 0.25s ease' }}>
            {children}
        </Box>
    )
}

// Export tab configuration for use in main config
export { TABS, TAB_WIDGETS }

// WidgetCard - Consistent wrapper for all dashboard widgets
// Provides collapsible functionality, consistent styling, and loading states

'use client'

import { Card, Stack, Flex, Text, Button, Box } from '@sanity/ui'
import { useState, ReactNode } from 'react'
import { ChevronDown, MoreVertical } from 'lucide-react'

interface WidgetCardProps {
    title: string
    icon?: ReactNode
    iconColor?: string
    children: ReactNode
    loading?: boolean
    error?: string
    collapsible?: boolean
    defaultCollapsed?: boolean
    headerGradient?: string
    actions?: ReactNode
    footer?: ReactNode
    compact?: boolean
}

export function WidgetCard({
    title,
    icon,
    iconColor = '#6366f1',
    children,
    loading = false,
    error,
    collapsible = true,
    defaultCollapsed = false,
    headerGradient,
    actions,
    footer,
    compact = false
}: WidgetCardProps) {
    const [collapsed, setCollapsed] = useState(defaultCollapsed)

    const toggleCollapse = () => {
        if (collapsible) {
            setCollapsed(!collapsed)
        }
    }

    return (
        <Card
            padding={0}
            radius={3}
            style={{
                overflow: 'hidden',
                transition: 'box-shadow 0.25s ease',
            }}
        >
            {/* Header */}
            <Box
                padding={3}
                style={{
                    background: headerGradient || 'transparent',
                    borderBottom: headerGradient ? 'none' : '1px solid rgba(255,255,255,0.1)',
                    cursor: collapsible ? 'pointer' : 'default'
                }}
                onClick={toggleCollapse}
            >
                <Flex justify="space-between" align="center">
                    <Flex align="center" gap={2}>
                        {icon && (
                            <Box style={{ color: headerGradient ? 'white' : iconColor }}>
                                {icon}
                            </Box>
                        )}
                        <Text
                            size={1}
                            weight="semibold"
                            style={{ color: headerGradient ? 'white' : 'inherit' }}
                        >
                            {title}
                        </Text>
                    </Flex>

                    <Flex align="center" gap={1}>
                        {actions && (
                            <Box onClick={(e) => e.stopPropagation()}>
                                {actions}
                            </Box>
                        )}
                        {collapsible && (
                            <Button
                                icon={
                                    <span style={{
                                        display: 'inline-flex',
                                        alignItems: 'center',
                                        justifyContent: 'center',
                                        transform: collapsed ? 'rotate(-90deg)' : 'rotate(0deg)',
                                        transition: 'transform 0.25s ease'
                                    }}>
                                        <ChevronDown />
                                    </span>
                                }
                                mode="bleed"
                                style={{
                                    color: headerGradient ? 'white' : 'inherit',
                                    opacity: 0.7
                                }}
                                onClick={(e) => {
                                    e.stopPropagation()
                                    toggleCollapse()
                                }}
                            />
                        )}
                    </Flex>
                </Flex>
            </Box>

            {/* Content */}
            <Box
                style={{
                    maxHeight: collapsed ? 0 : 2000,
                    opacity: collapsed ? 0 : 1,
                    overflow: 'hidden',
                    transition: 'max-height 0.3s ease, opacity 0.2s ease'
                }}
            >
                {loading ? (
                    <Box padding={compact ? 3 : 4}>
                        <LoadingSkeleton lines={3} />
                    </Box>
                ) : error ? (
                    <Box padding={compact ? 3 : 4}>
                        <Card padding={3} tone="critical" radius={2}>
                            <Text size={1}>{error}</Text>
                        </Card>
                    </Box>
                ) : (
                    <Box padding={compact ? 3 : 4}>
                        {children}
                    </Box>
                )}

                {/* Footer */}
                {footer && !collapsed && (
                    <Box
                        padding={3}
                        style={{
                            borderTop: '1px solid rgba(255,255,255,0.1)',
                            background: 'rgba(255,255,255,0.02)'
                        }}
                    >
                        {footer}
                    </Box>
                )}
            </Box>
        </Card>
    )
}

// Loading Skeleton Component
interface LoadingSkeletonProps {
    lines?: number
    showTitle?: boolean
}

export function LoadingSkeleton({ lines = 3, showTitle = false }: LoadingSkeletonProps) {
    return (
        <Stack space={3}>
            {showTitle && (
                <Box
                    style={{
                        height: 20,
                        width: '60%',
                        background: 'linear-gradient(90deg, rgba(255,255,255,0.05) 25%, rgba(255,255,255,0.1) 50%, rgba(255,255,255,0.05) 75%)',
                        backgroundSize: '200% 100%',
                        animation: 'skeleton-pulse 1.5s ease-in-out infinite',
                        borderRadius: 4
                    }}
                />
            )}
            {Array.from({ length: lines }).map((_, i) => (
                <Box
                    key={i}
                    style={{
                        height: 14,
                        width: `${100 - (i * 15)}%`,
                        background: 'linear-gradient(90deg, rgba(255,255,255,0.05) 25%, rgba(255,255,255,0.1) 50%, rgba(255,255,255,0.05) 75%)',
                        backgroundSize: '200% 100%',
                        animation: 'skeleton-pulse 1.5s ease-in-out infinite',
                        animationDelay: `${i * 0.1}s`,
                        borderRadius: 4
                    }}
                />
            ))}
        </Stack>
    )
}

// Stats Grid Component
interface Stat {
    label: string
    value: string | number
    tone?: 'default' | 'primary' | 'positive' | 'caution' | 'critical'
    icon?: ReactNode
    change?: string
}

interface StatsGridProps {
    stats: Stat[]
    columns?: 2 | 3 | 4 | 5
}

export function StatsGrid({ stats, columns = 4 }: StatsGridProps) {
    const getToneColor = (tone?: string) => {
        switch (tone) {
            case 'positive': return '#10b981'
            case 'caution': return '#f59e0b'
            case 'critical': return '#ef4444'
            case 'primary': return '#6366f1'
            default: return undefined
        }
    }

    return (
        <Flex gap={2} wrap="wrap">
            {stats.map((stat, i) => (
                <Card
                    key={i}
                    padding={3}
                    tone={stat.tone || 'default'}
                    radius={2}
                    style={{
                        flex: `1 1 calc(${100 / columns}% - 8px)`,
                        minWidth: '100px',
                        textAlign: 'center',
                        transition: 'transform 0.15s ease'
                    }}
                >
                    <Stack space={2}>
                        {stat.icon && (
                            <Flex justify="center">
                                <Box style={{ color: getToneColor(stat.tone), opacity: 0.8 }}>
                                    {stat.icon}
                                </Box>
                            </Flex>
                        )}
                        <Text
                            size={3}
                            weight="bold"
                            style={{ color: getToneColor(stat.tone) }}
                        >
                            {stat.value}
                        </Text>
                        <Text size={0} muted style={{ textTransform: 'uppercase', letterSpacing: '0.5px', fontWeight: 500 }}>
                            {stat.label}
                        </Text>
                        {stat.change && (
                            <Text size={0} style={{ color: stat.change.startsWith('+') ? '#10b981' : '#ef4444' }}>
                                {stat.change}
                            </Text>
                        )}
                    </Stack>
                </Card>
            ))}
        </Flex>
    )
}

// Action Bar Component
interface Action {
    label: string
    icon?: ReactNode
    onClick: () => void
    tone?: 'default' | 'primary' | 'positive' | 'caution' | 'critical'
    disabled?: boolean
    loading?: boolean
}

interface ActionBarProps {
    actions: Action[]
    align?: 'left' | 'center' | 'right'
}

export function ActionBar({ actions, align = 'left' }: ActionBarProps) {
    const justifyMap = {
        left: 'flex-start',
        center: 'center',
        right: 'flex-end'
    }

    return (
        <Flex gap={2} wrap="wrap" justify={justifyMap[align] as any}>
            {actions.map((action, i) => (
                <Button
                    key={i}
                    text={action.label}
                    icon={action.icon}
                    onClick={action.onClick}
                    tone={action.tone}
                    disabled={action.disabled || action.loading}
                    mode="ghost"
                    fontSize={1}
                />
            ))}
        </Flex>
    )
}

// Progress Bar Component
interface ProgressBarProps {
    value: number
    max?: number
    color?: string
    animated?: boolean
    showLabel?: boolean
}

export function ProgressBar({
    value,
    max = 100,
    color = '#6366f1',
    animated = false,
    showLabel = false
}: ProgressBarProps) {
    const percentage = Math.min((value / max) * 100, 100)

    return (
        <Stack space={1}>
            {showLabel && (
                <Flex justify="space-between">
                    <Text size={0} muted>Progress</Text>
                    <Text size={0} muted>{Math.round(percentage)}%</Text>
                </Flex>
            )}
            <Box
                style={{
                    height: 4,
                    background: 'rgba(255,255,255,0.1)',
                    borderRadius: 2,
                    overflow: 'hidden'
                }}
            >
                <Box
                    style={{
                        height: '100%',
                        width: `${percentage}%`,
                        background: color,
                        borderRadius: 2,
                        transition: 'width 0.3s ease',
                        animation: animated ? 'progress-glow 2s ease-in-out infinite' : 'none'
                    }}
                />
            </Box>
        </Stack>
    )
}

// Empty State Component
interface EmptyStateProps {
    icon?: ReactNode
    title: string
    description?: string
    action?: ReactNode
}

export function EmptyState({ icon, title, description, action }: EmptyStateProps) {
    return (
        <Stack space={3} style={{ textAlign: 'center', padding: '32px 16px' }}>
            {icon && (
                <Box style={{ opacity: 0.2 }}>
                    {icon}
                </Box>
            )}
            <Text size={1} weight="medium">{title}</Text>
            {description && (
                <Text size={1} muted>{description}</Text>
            )}
            {action && (
                <Box style={{ marginTop: 8 }}>
                    {action}
                </Box>
            )}
        </Stack>
    )
}

// useWidgetData - Optimized data fetching hook with caching
// For consistent data fetching patterns across widgets

'use client'

import { useState, useEffect, useCallback, useRef } from 'react'
import { useClient } from 'sanity'
import { apiVersion } from '../env'

interface CacheEntry {
    data: any
    timestamp: number
}

// Simple in-memory cache
const dataCache = new Map<string, CacheEntry>()

interface UseWidgetDataOptions {
    query: string
    params?: Record<string, any>
    cacheKey?: string
    cacheDuration?: number // in milliseconds, default 60 seconds
    enabled?: boolean
    onSuccess?: (data: any) => void
    onError?: (error: Error) => void
}

interface UseWidgetDataResult<T> {
    data: T | null
    loading: boolean
    error: string | null
    refetch: () => Promise<void>
    isStale: boolean
}

export function useWidgetData<T = any>({
    query,
    params = {},
    cacheKey,
    cacheDuration = 60000, // 1 minute default
    enabled = true,
    onSuccess,
    onError
}: UseWidgetDataOptions): UseWidgetDataResult<T> {
    const client = useClient({ apiVersion })
    const [data, setData] = useState<T | null>(null)
    const [loading, setLoading] = useState(true)
    const [error, setError] = useState<string | null>(null)
    const [isStale, setIsStale] = useState(false)
    const abortControllerRef = useRef<AbortController | null>(null)

    // Generate cache key if not provided
    const effectiveCacheKey = cacheKey || `${query}-${JSON.stringify(params)}`

    const fetchData = useCallback(async (skipCache = false) => {
        if (!enabled) {
            setLoading(false)
            return
        }

        // Check cache first (unless skipping)
        if (!skipCache && cacheDuration > 0) {
            const cached = dataCache.get(effectiveCacheKey)
            if (cached) {
                const age = Date.now() - cached.timestamp
                if (age < cacheDuration) {
                    setData(cached.data)
                    setLoading(false)
                    setIsStale(false)
                    return
                } else {
                    // Data is stale but usable
                    setData(cached.data)
                    setIsStale(true)
                }
            }
        }

        setLoading(true)
        setError(null)

        // Abort any pending request
        if (abortControllerRef.current) {
            abortControllerRef.current.abort()
        }
        abortControllerRef.current = new AbortController()

        try {
            const result = await client.fetch(query, params)

            // Store in cache
            if (cacheDuration > 0) {
                dataCache.set(effectiveCacheKey, {
                    data: result,
                    timestamp: Date.now()
                })
            }

            setData(result)
            setIsStale(false)
            onSuccess?.(result)
        } catch (err) {
            // Don't set error if aborted
            if ((err as Error).name !== 'AbortError') {
                const errorMessage = err instanceof Error ? err.message : 'Failed to fetch data'
                setError(errorMessage)
                onError?.(err as Error)
            }
        } finally {
            setLoading(false)
        }
    }, [client, query, JSON.stringify(params), effectiveCacheKey, cacheDuration, enabled])

    useEffect(() => {
        fetchData()

        return () => {
            if (abortControllerRef.current) {
                abortControllerRef.current.abort()
            }
        }
    }, [fetchData])

    const refetch = useCallback(async () => {
        await fetchData(true) // Skip cache
    }, [fetchData])

    return { data, loading, error, refetch, isStale }
}

// useLocalStorage - Persist state to localStorage
export function useLocalStorage<T>(
    key: string,
    initialValue: T
): [T, (value: T | ((prev: T) => T)) => void] {
    const [storedValue, setStoredValue] = useState<T>(() => {
        if (typeof window === 'undefined') return initialValue

        try {
            const item = window.localStorage.getItem(key)
            return item ? JSON.parse(item) : initialValue
        } catch (error) {
            console.error(`Error reading localStorage key "${key}":`, error)
            return initialValue
        }
    })

    const setValue = useCallback((value: T | ((prev: T) => T)) => {
        try {
            const valueToStore = value instanceof Function ? value(storedValue) : value
            setStoredValue(valueToStore)

            if (typeof window !== 'undefined') {
                window.localStorage.setItem(key, JSON.stringify(valueToStore))
            }
        } catch (error) {
            console.error(`Error setting localStorage key "${key}":`, error)
        }
    }, [key, storedValue])

    return [storedValue, setValue]
}

// useDebounce - Debounce a value
export function useDebounce<T>(value: T, delay: number = 300): T {
    const [debouncedValue, setDebouncedValue] = useState<T>(value)

    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedValue(value)
        }, delay)

        return () => {
            clearTimeout(timer)
        }
    }, [value, delay])

    return debouncedValue
}

// useInterval - Run callback at intervals
export function useInterval(callback: () => void, delay: number | null) {
    const savedCallback = useRef(callback)

    useEffect(() => {
        savedCallback.current = callback
    }, [callback])

    useEffect(() => {
        if (delay === null) return

        const tick = () => savedCallback.current()
        const id = setInterval(tick, delay)

        return () => clearInterval(id)
    }, [delay])
}

// Helper to clear cache
export function clearWidgetCache(key?: string) {
    if (key) {
        dataCache.delete(key)
    } else {
        dataCache.clear()
    }
}

// Helper to get cache stats
export function getCacheStats() {
    return {
        size: dataCache.size,
        keys: Array.from(dataCache.keys())
    }
}

import type { SanityClient } from '@sanity/client'

export interface ExportResult {
    success: boolean
    message: string
    count?: number
}

export interface DeleteResult {
    success: boolean
    message: string
    deletedCount?: number
}

export interface ImportResult {
    success: boolean
    message: string
    importedCount?: number
}

export interface PublishResult {
    success: boolean
    message: string
    publishedCount?: number
}

export interface ValidationResult {
    success: boolean
    message: string
    issues: ValidationIssue[]
}

export interface ValidationIssue {
    collegeId: string
    collegeName: string
    issues: string[]
}

export interface RebuildResult {
    success: boolean
    message: string
}

/**
 * Export colleges to JSON or CSV format
 */
export async function exportColleges(
    client: SanityClient,
    format: 'json' | 'csv'
): Promise<ExportResult> {
    try {
        const colleges = await client.fetch(`*[_type == "college"] | order(name asc) {
            _id,
            name,
            slug,
            location,
            type,
            estYear,
            website,
            isVisible,
            priority,
            cutoffIdentifier,
            lastSyncedAt
        }`)

        if (!colleges || colleges.length === 0) {
            return { success: false, message: 'No colleges found to export' }
        }

        if (format === 'json') {
            const dataStr = JSON.stringify(colleges, null, 2)
            const dataBlob = new Blob([dataStr], { type: 'application/json' })
            const url = URL.createObjectURL(dataBlob)
            const link = document.createElement('a')
            link.href = url
            link.download = `colleges-export-${new Date().toISOString().split('T')[0]}.json`
            link.click()
            URL.revokeObjectURL(url)
        } else {
            // CSV export
            const headers = ['ID', 'Name', 'Slug', 'Location', 'Type', 'Est. Year', 'Website', 'Visible', 'Priority', 'Cutoff ID', 'Last Synced']
            interface ExportCollege {
                _id: string
                name: string
                slug?: { current: string }
                location: string
                type: string
                estYear?: number
                website?: string
                isVisible: boolean
                priority: number
                cutoffIdentifier?: string
                lastSyncedAt?: string
            }

            const rows = (colleges as ExportCollege[]).map((c) => [
                c._id,
                c.name,
                c.slug?.current || '',
                c.location,
                c.type,
                c.estYear || '',
                c.website || '',
                c.isVisible ? 'Yes' : 'No',
                c.priority,
                c.cutoffIdentifier || '',
                c.lastSyncedAt || ''
            ])

            const csvContent = [
                headers.join(','),
                ...rows.map((row) => row.map((cell) => `"${cell}"`).join(','))
            ].join('\n')

            const dataBlob = new Blob([csvContent], { type: 'text/csv' })
            const url = URL.createObjectURL(dataBlob)
            const link = document.createElement('a')
            link.href = url
            link.download = `colleges-export-${new Date().toISOString().split('T')[0]}.csv`
            link.click()
            URL.revokeObjectURL(url)
        }

        return {
            success: true,
            message: `Exported ${colleges.length} colleges as ${format.toUpperCase()}`,
            count: colleges.length
        }
    } catch (error) {
        const message = error instanceof Error ? error.message : 'Export failed'
        return { success: false, message }
    }
}

/**
 * Delete all college documents
 */
export async function deleteAllColleges(client: SanityClient): Promise<DeleteResult> {
    try {
        const colleges = await client.fetch(`*[_type == "college"]{ _id }`)

        if (!colleges || colleges.length === 0) {
            return { success: false, message: 'No colleges found to delete' }
        }

        const mutations = (colleges as { _id: string }[]).map((c) => ({ delete: { id: c._id } }))
        await client.transaction(mutations).commit()

        return {
            success: true,
            message: `Deleted ${colleges.length} colleges`,
            deletedCount: colleges.length
        }
    } catch (error) {
        const message = error instanceof Error ? error.message : 'Delete failed'
        return { success: false, message }
    }
}

/**
 * Import colleges from JSON file
 */
export async function importCollegesFromJSON(
    client: SanityClient,
    file: File
): Promise<ImportResult> {
    try {
        const text = await file.text()
        const data = JSON.parse(text)

        if (!Array.isArray(data)) {
            return { success: false, message: 'Invalid JSON format. Expected an array of colleges.' }
        }

        let imported = 0
        let skipped = 0

        for (const item of data) {
            try {
                // Remove _id if present (we want Sanity to generate new ones)
                const { _id: _unusedId, ...rest } = item

                // Ensure required fields
                if (!rest.name || !rest.slug) {
                    skipped++
                    continue
                }

                await client.create({
                    _type: 'college',
                    ...rest
                })
                imported++
            } catch (err) {
                skipped++
                console.error('Failed to import:', item.name, err)
            }
        }

        return {
            success: true,
            message: `Imported ${imported} colleges (${skipped} skipped)`,
            importedCount: imported
        }
    } catch (error) {
        const message = error instanceof Error ? error.message : 'Import failed'
        return { success: false, message }
    }
}

/**
 * Import colleges from CSV file
 */
export async function importCollegesFromCSV(
    client: SanityClient,
    file: File
): Promise<ImportResult> {
    try {
        const text = await file.text()

        // Use CSV parsing utilities
        const { parseCSV, validateRow } = await import('./csvImport')
        const parseResult = parseCSV(text)

        if (parseResult.errors.length > 0) {
            return {
                success: false,
                message: `CSV parsing errors:\n${parseResult.errors.join('\n')}`
            }
        }

        if (parseResult.rows.length === 0) {
            return { success: false, message: 'No data rows found in CSV' }
        }

        let imported = 0
        let updated = 0
        let skipped = 0
        const errors: string[] = []

        for (let i = 0; i < parseResult.rows.length; i++) {
            const row = parseResult.rows[i]
            const rowNum = i + 2 // +2 because of header row and 0-indexing

            try {
                // Validate row
                const validationErrors = validateRow(row)
                if (validationErrors.length > 0) {
                    errors.push(`Row ${rowNum}: ${validationErrors.join(', ')}`)
                    skipped++
                    continue
                }

                // Generate slug from name
                const slug = row.name
                    .toLowerCase()
                    .replace(/[^a-z0-9]+/g, '-')
                    .replace(/^-|-$/g, '')

                // Check if college already exists by name
                const existing = await client.fetch(
                    `*[_type == "college" && name == $name][0]`,
                    { name: row.name }
                )

                const collegeData = {
                    _type: 'college' as const,
                    name: row.name,
                    slug: { _type: 'slug' as const, current: slug },
                    location: row.location,
                    type: row.type as 'Government' | 'Private' | 'Semi-Govt',
                    estYear: row.estYear ? parseInt(row.estYear) : undefined,
                    website: row.website || undefined,
                    shortName: row.shortName || undefined,
                    isVisible: row.isVisible ? row.isVisible.toLowerCase() === 'true' : true,
                    description: row.description || undefined,
                    priority: 0
                }

                if (existing) {
                    // Update existing college
                    await client
                        .patch(existing._id)
                        .set(collegeData)
                        .commit()
                    updated++
                } else {
                    // Create new college
                    await client.create(collegeData)
                    imported++
                }
            } catch (err) {
                const errorMsg = err instanceof Error ? err.message : 'Unknown error'
                errors.push(`Row ${rowNum} (${row.name}): ${errorMsg}`)
                skipped++
            }
        }

        const summary = [
            `Imported: ${imported} new`,
            `Updated: ${updated} existing`,
            skipped > 0 ? `Skipped: ${skipped}` : null
        ].filter(Boolean).join(', ')

        return {
            success: true,
            message: errors.length > 0
                ? `${summary}\n\nErrors:\n${errors.slice(0, 10).join('\n')}${errors.length > 10 ? `\n...and ${errors.length - 10} more` : ''}`
                : summary,
            importedCount: imported + updated
        }
    } catch (error) {
        const message = error instanceof Error ? error.message : 'CSV import failed'
        return { success: false, message }
    }
}

/**
 * Publish all draft college documents
 */
export async function publishAllDrafts(client: SanityClient): Promise<PublishResult> {
    try {
        const drafts = await client.fetch(`*[_type == "college" && _id in path("drafts.**")]`)

        if (!drafts || drafts.length === 0) {
            return { success: false, message: 'No drafts found' }
        }

        let published = 0
        for (const draft of drafts) {
            try {
                const docId = draft._id.replace('drafts.', '')
                const { _id: _draftId, _rev: _draftRev, ...content } = draft

                await client.createOrReplace({
                    _id: docId,
                    ...content
                })

                await client.delete(draft._id)
                published++
            } catch (err) {
                console.error('Failed to publish:', draft._id, err)
            }
        }

        return {
            success: true,
            message: `Published ${published} drafts`,
            publishedCount: published
        }
    } catch (error) {
        const message = error instanceof Error ? error.message : 'Publish failed'
        return { success: false, message }
    }
}

/**
 * Validate all colleges and return issues
 */
export async function validateAllColleges(client: SanityClient): Promise<ValidationResult> {
    try {
        const colleges = await client.fetch(`*[_type == "college"]{
            _id,
            name,
            slug,
            location,
            type,
            logo,
            description,
            highlights,
            detailsIdentifier
        }`)

        const issues: ValidationIssue[] = []

        for (const college of colleges) {
            const collegeIssues: string[] = []

            if (!college.slug?.current) {
                collegeIssues.push('Missing URL slug')
            }
            if (!college.location) {
                collegeIssues.push('Missing location')
            }
            if (!college.type) {
                collegeIssues.push('Missing college type')
            }
            if (!college.logo) {
                collegeIssues.push('Missing logo')
            }
            if (!college.description) {
                collegeIssues.push('Missing meta description')
            }
            if (!college.highlights || college.highlights.length === 0) {
                collegeIssues.push('Missing highlights')
            }
            if (!college.detailsIdentifier) {
                collegeIssues.push('No detail source linked')
            }

            if (collegeIssues.length > 0) {
                issues.push({
                    collegeId: college._id,
                    collegeName: college.name,
                    issues: collegeIssues
                })
            }
        }

        return {
            success: true,
            message: issues.length === 0
                ? 'All colleges passed validation!'
                : `Found ${issues.length} colleges with issues`,
            issues
        }
    } catch (error) {
        const message = error instanceof Error ? error.message : 'Validation failed'
        return { success: false, message, issues: [] }
    }
}

/**
 * Rebuild all data by triggering revalidation webhook
 */
export async function rebuildAllData(includeCollections: string[]): Promise<RebuildResult> {
    try {
        const collections = includeCollections.join(',')
        const response = await fetch(`/api/revalidate?secret=${process.env.NEXT_PUBLIC_REVALIDATE_SECRET}&rebuild=all&collections=${collections}`)

        if (!response.ok) {
            throw new Error(`Rebuild failed: ${response.statusText}`)
        }

        const data = await response.json()
        return {
            success: true,
            message: data.message || 'Rebuild triggered successfully'
        }
    } catch (error) {
        const message = error instanceof Error ? error.message : 'Rebuild failed'
        return { success: false, message }
    }
}

/**
 * Duplicate Detection System
 * Identifies potential duplicate college entries using fuzzy matching
 */

import { SanityClient } from '@sanity/client'

export interface DuplicateMatch {
    college1: {
        _id: string
        name: string
        location: string
        type: string
    }
    college2: {
        _id: string
        name: string
        location: string
        type: string
    }
    similarity: number // 0-100
    reasons: string[]
}

export interface DuplicateGroup {
    colleges: Array<{
        _id: string
        name: string
        location: string
        type: string
        isVisible: boolean
    }>
    similarity: number
    suggestedPrimary: string // ID of suggested college to keep
}

/**
 * Calculate similarity between two strings using Levenshtein distance
 */
function calculateSimilarity(str1: string, str2: string): number {
    const s1 = str1.toLowerCase().trim()
    const s2 = str2.toLowerCase().trim()

    if (s1 === s2) return 100

    const len1 = s1.length
    const len2 = s2.length

    if (len1 === 0 || len2 === 0) return 0

    // Levenshtein distance matrix
    const matrix: number[][] = []

    for (let i = 0; i <= len1; i++) {
        matrix[i] = [i]
    }

    for (let j = 0; j <= len2; j++) {
        matrix[0][j] = j
    }

    for (let i = 1; i <= len1; i++) {
        for (let j = 1; j <= len2; j++) {
            const cost = s1[i - 1] === s2[j - 1] ? 0 : 1
            matrix[i][j] = Math.min(
                matrix[i - 1][j] + 1,      // deletion
                matrix[i][j - 1] + 1,      // insertion
                matrix[i - 1][j - 1] + cost // substitution
            )
        }
    }

    const distance = matrix[len1][len2]
    const maxLen = Math.max(len1, len2)
    const similarity = ((maxLen - distance) / maxLen) * 100

    return Math.round(similarity)
}

/**
 * Normalize college name for comparison
 */
function normalizeName(name: string): string {
    return name
        .toLowerCase()
        .replace(/\s+/g, ' ')
        .replace(/[^\w\s]/g, '')
        .replace(/\b(college|university|institute|of|engineering|management|technology|science)\b/g, '')
        .trim()
}

/**
 * Check if two colleges are potential duplicates
 */
interface CollegeCandidate {
    _id: string
    name: string
    location?: string
    type?: string
    shortName?: string
    website?: string
    isVisible?: boolean
}

function arePotentialDuplicates(
    college1: CollegeCandidate,
    college2: CollegeCandidate,
    threshold: number = 70
): DuplicateMatch | null {
    const reasons: string[] = []
    let totalSimilarity = 0
    let factorCount = 0

    // 1. Name similarity (most important)
    const nameSimilarity = calculateSimilarity(
        normalizeName(college1.name),
        normalizeName(college2.name)
    )

    if (nameSimilarity >= threshold) {
        reasons.push(`Name similarity: ${nameSimilarity}%`)
        totalSimilarity += nameSimilarity * 2 // Double weight
        factorCount += 2
    } else if (nameSimilarity < 50) {
        // Names too different, not a duplicate
        return null
    }

    // 2. Location similarity
    if (college1.location && college2.location) {
        const locationSimilarity = calculateSimilarity(
            college1.location.toLowerCase(),
            college2.location.toLowerCase()
        )

        if (locationSimilarity >= 80) {
            reasons.push(`Same location: ${college1.location}`)
            totalSimilarity += locationSimilarity
            factorCount++
        }
    }

    // 3. Same type
    if (college1.type === college2.type) {
        reasons.push(`Same type: ${college1.type}`)
        totalSimilarity += 100
        factorCount++
    }

    // 4. Check for common abbreviations
    if (college1.shortName && college2.shortName) {
        if (college1.shortName.toLowerCase() === college2.shortName.toLowerCase()) {
            reasons.push(`Same acronym: ${college1.shortName}`)
            totalSimilarity += 100
            factorCount++
        }
    }

    // 5. Website similarity
    if (college1.website && college2.website) {
        const domain1 = extractDomain(college1.website)
        const domain2 = extractDomain(college2.website)

        if (domain1 === domain2) {
            reasons.push(`Same website domain: ${domain1}`)
            totalSimilarity += 100
            factorCount++
        }
    }

    // Calculate average similarity
    const avgSimilarity = factorCount > 0 ? Math.round(totalSimilarity / factorCount) : 0

    if (avgSimilarity >= threshold && reasons.length >= 2) {
        return {
            college1: {
                _id: college1._id,
                name: college1.name,
                location: college1.location || '',
                type: college1.type || ''
            },
            college2: {
                _id: college2._id,
                name: college2.name,
                location: college2.location || '',
                type: college2.type || ''
            },
            similarity: avgSimilarity,
            reasons
        }
    }

    return null
}

/**
 * Extract domain from URL
 */
function extractDomain(url: string): string {
    try {
        const urlObj = new URL(url)
        return urlObj.hostname.replace('www.', '')
    } catch {
        return url
    }
}

/**
 * Find all potential duplicates in the database
 */
export async function findDuplicates(
    client: SanityClient,
    threshold: number = 70
): Promise<DuplicateMatch[]> {
    // Fetch all colleges
    const colleges = await client.fetch(`
        *[_type == "college"] {
            _id, name, location, type, shortName, website, isVisible
        }
    `)

    const duplicates: DuplicateMatch[] = []
    const checked = new Set<string>()

    // Compare each college with every other college
    for (let i = 0; i < colleges.length; i++) {
        for (let j = i + 1; j < colleges.length; j++) {
            const pairKey = [colleges[i]._id, colleges[j]._id].sort().join('-')

            if (checked.has(pairKey)) continue
            checked.add(pairKey)

            const match = arePotentialDuplicates(colleges[i], colleges[j], threshold)
            if (match) {
                duplicates.push(match)
            }
        }
    }

    // Sort by similarity (highest first)
    return duplicates.sort((a, b) => b.similarity - a.similarity)
}

/**
 * Group duplicates together
 */
export function groupDuplicates(matches: DuplicateMatch[]): DuplicateGroup[] {
    const groups: Map<string, Set<string>> = new Map()

    // Build groups
    matches.forEach(match => {
        const id1 = match.college1._id
        const id2 = match.college2._id

        // Find existing group
        let foundGroup: Set<string> | null = null
        for (const [_key, group] of groups.entries()) {
            if (group.has(id1) || group.has(id2)) {
                foundGroup = group
                break
            }
        }

        if (foundGroup) {
            foundGroup.add(id1)
            foundGroup.add(id2)
        } else {
            const newGroup = new Set([id1, id2])
            groups.set(id1, newGroup)
        }
    })

    // Convert to array format
    const result: DuplicateGroup[] = []
    const processed = new Set<string>()

    for (const [key, group] of groups.entries()) {
        if (processed.has(key)) continue

        const groupIds = Array.from(group)
        groupIds.forEach(id => processed.add(id))

        // Find colleges in this group
        const groupColleges = matches
            .filter(m => groupIds.includes(m.college1._id) || groupIds.includes(m.college2._id))
            .flatMap(m => [
                { ...m.college1, isVisible: false }, // Add isVisible property
                { ...m.college2, isVisible: false }
            ])
            .filter((c, i, arr) => arr.findIndex(x => x._id === c._id) === i)

        // Calculate average similarity
        const relevantMatches = matches.filter(m =>
            groupIds.includes(m.college1._id) && groupIds.includes(m.college2._id)
        )
        const avgSimilarity = relevantMatches.length > 0
            ? Math.round(relevantMatches.reduce((sum, m) => sum + m.similarity, 0) / relevantMatches.length)
            : 0

        // Suggest primary (prefer visible, then alphabetically first)
        const suggested = groupColleges.sort((a, b) => {
            if (a.isVisible !== b.isVisible) return a.isVisible ? -1 : 1
            return a.name.localeCompare(b.name)
        })[0]

        result.push({
            colleges: groupColleges,
            similarity: avgSimilarity,
            suggestedPrimary: suggested._id
        })
    }

    return result.sort((a, b) => b.similarity - a.similarity)
}

/**
 * Merge duplicate colleges
 */
export async function mergeDuplicates(
    client: SanityClient,
    primaryId: string,
    duplicateIds: string[]
): Promise<{ success: boolean; message: string }> {
    try {
        // Fetch primary college
        const primary = await client.getDocument(primaryId)
        if (!primary) {
            return { success: false, message: 'Primary college not found' }
        }

        // Fetch duplicates
        const duplicates = await Promise.all(
            duplicateIds.map(id => client.getDocument(id))
        )

        // Merge data (keep primary, fill in missing fields from duplicates)
        const merged: Record<string, unknown> = { ...primary }

        duplicates.forEach(dup => {
            if (!dup) return

            // Fill in missing fields
            Object.keys(dup).forEach(key => {
                if (key.startsWith('_')) return // Skip system fields
                if (!merged[key] && dup[key]) {
                    merged[key] = dup[key]
                }
            })
        })

        // Update primary with merged data
        await client.patch(primaryId).set(merged).commit()

        // Delete duplicates
        const transaction = client.transaction()
        duplicateIds.forEach(id => {
            transaction.delete(id)
        })
        await transaction.commit()

        return {
            success: true,
            message: `Merged ${duplicateIds.length} duplicate(s) into ${primary.name}`
        }
    } catch (error) {
        const message = error instanceof Error ? error.message : 'Unknown error'
        return { success: false, message: `Merge failed: ${message}` }
    }
}
